DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`odtjonaf`@`localhost` PROCEDURE `cleanup_expired_carts` ()   BEGIN
  DELETE FROM `carts` WHERE `expires_at` < NOW();
  SELECT ROW_COUNT() as deleted_carts;
END$$

CREATE DEFINER=`odtjonaf`@`localhost` PROCEDURE `generate_order_number` (OUT `order_num` VARCHAR(50))   BEGIN
  DECLARE year_part VARCHAR(4);
  DECLARE counter INT;
  
  SET year_part = YEAR(NOW());
  
  SELECT COALESCE(MAX(CAST(SUBSTRING(order_number, -4) AS UNSIGNED)), 0) + 1 
  INTO counter
  FROM orders 
  WHERE order_number LIKE CONCAT('ORD-', year_part, '-%');
  
  SET order_num = CONCAT('ORD-', year_part, '-', LPAD(counter, 4, '0'));
END$$

CREATE DEFINER=`odtjonaf`@`localhost` PROCEDURE `get_order_statistics` (IN `start_date` DATE, IN `end_date` DATE)   BEGIN
  SELECT 
    COUNT(*) as total_orders,
    SUM(CASE WHEN status = 'pending' THEN 1 ELSE 0 END) as pending_orders,
    SUM(CASE WHEN status = 'processing' THEN 1 ELSE 0 END) as processing_orders,
    SUM(CASE WHEN status = 'shipped' THEN 1 ELSE 0 END) as shipped_orders,
    SUM(CASE WHEN status = 'delivered' THEN 1 ELSE 0 END) as delivered_orders,
    SUM(CASE WHEN status = 'cancelled' THEN 1 ELSE 0 END) as cancelled_orders,
    SUM(CASE WHEN payment_status = 'paid' THEN total ELSE 0 END) as total_revenue,
    AVG(total) as average_order_value
  FROM orders
  WHERE DATE(created_at) BETWEEN start_date AND end_date;
END$$

DELIMITER ;

