--
-- Triggers `book_rates`
--
DELIMITER $$
CREATE TRIGGER `after_book_rate_insert` AFTER INSERT ON `book_rates` FOR EACH ROW BEGIN
  UPDATE `books`
  SET
    `avg_rating` = (SELECT AVG(rate) FROM book_rates WHERE book_id = NEW.book_id),
    `ratings_count` = (SELECT COUNT(*) FROM book_rates WHERE book_id = NEW.book_id)
  WHERE `id` = NEW.book_id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_book_rate_update` AFTER UPDATE ON `book_rates` FOR EACH ROW BEGIN
  UPDATE `books`
  SET
    `avg_rating` = (SELECT AVG(rate) FROM book_rates WHERE book_id = NEW.book_id),
    `ratings_count` = (SELECT COUNT(*) FROM book_rates WHERE book_id = NEW.book_id)
  WHERE `id` = NEW.book_id;
END
$$
DELIMITER ;

