CREATE TABLE `orders` (
  `id` bigint UNSIGNED NOT NULL,
  `order_number` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'شماره سفارش یکتا مثل ORD-2026-0001',
  `user_id` bigint UNSIGNED NOT NULL,
  `status` enum('pending','processing','shipped','delivered','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'وضعیت سفارش',
  `subtotal` decimal(10,2) NOT NULL COMMENT 'جمع قبل از تخفیف',
  `discount` decimal(10,2) DEFAULT '0.00' COMMENT 'مبلغ تخفیف',
  `tax` decimal(10,2) DEFAULT '0.00' COMMENT 'مالیات',
  `shipping_cost` decimal(10,2) DEFAULT '0.00' COMMENT 'هزینه ارسال',
  `total` decimal(10,2) NOT NULL COMMENT 'مبلغ نهایی قابل پرداخت',
  `payment_method` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'روش پرداخت: online, cash, etc',
  `payment_status` enum('unpaid','paid','refunded') COLLATE utf8mb4_unicode_ci DEFAULT 'unpaid' COMMENT 'وضعیت پرداخت',
  `payment_transaction_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'شناسه تراکنش پرداخت',
  `payment_date` timestamp NULL DEFAULT NULL COMMENT 'تاریخ پرداخت',
  `notes` text COLLATE utf8mb4_unicode_ci COMMENT 'یادداشت‌های مدیر',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='سفارشات ثبت شده';

--
-- Triggers `orders`
--
DELIMITER $$
CREATE TRIGGER `log_order_status_change` AFTER UPDATE ON `orders` FOR EACH ROW BEGIN
  IF OLD.status != NEW.status THEN
    VALUES (NEW.id, OLD.status, NEW.status, NEW.notes);
  END IF;
END
$$
DELIMITER ;

