--
-- Triggers `order_items`
--
DELIMITER $$
CREATE TRIGGER `calculate_order_item_total` BEFORE INSERT ON `order_items` FOR EACH ROW BEGIN
  IF NEW.unit_price IS NOT NULL AND NEW.quantity IS NOT NULL THEN
    SET NEW.total_price = NEW.unit_price * NEW.quantity;
  END IF;
END
$$
DELIMITER ;

