DELIMITER $$
CREATE TRIGGER `after_story_rate_update` AFTER UPDATE ON `story_rates` FOR EACH ROW BEGIN
  UPDATE `stories`
  SET
    `avg_rating` = (SELECT AVG(rate) FROM story_rates WHERE story_id = NEW.story_id),
    `ratings_count` = (SELECT COUNT(*) FROM story_rates WHERE story_id = NEW.story_id)
  WHERE `id` = NEW.story_id;
END
$$
DELIMITER ;

