--
-- Structure for view `orders_with_user_info`
--
DROP TABLE IF EXISTS `orders_with_user_info`;

CREATE ALGORITHM=UNDEFINED DEFINER=`odtjonaf`@`localhost` SQL SECURITY DEFINER VIEW `orders_with_user_info`  AS SELECT `o`.`id` AS `id`, `o`.`order_number` AS `order_number`, `o`.`status` AS `status`, `o`.`payment_status` AS `payment_status`, `o`.`total` AS `total`, `o`.`created_at` AS `created_at`, `u`.`id` AS `user_id`, `u`.`phone_number` AS `user_phone`, concat(`u`.`name`,' ',`u`.`family_name`) AS `user_name` FROM (`orders` `o` join `users` `u` on((`o`.`user_id` = `u`.`id`))) ;

-- --------------------------------------------------------

--
-- Structure for view `product_sales_stats`
--
DROP TABLE IF EXISTS `product_sales_stats`;

CREATE ALGORITHM=UNDEFINED DEFINER=`odtjonaf`@`localhost` SQL SECURITY DEFINER VIEW `product_sales_stats`  AS SELECT `oi`.`product_type` AS `product_type`, `oi`.`product_id` AS `product_id`, `oi`.`product_name` AS `product_name`, count(0) AS `times_sold`, sum(`oi`.`quantity`) AS `total_quantity_sold`, sum(`oi`.`total_price`) AS `total_revenue` FROM (`order_items` `oi` join `orders` `o` on((`oi`.`order_id` = `o`.`id`))) WHERE (`o`.`payment_status` = 'paid') GROUP BY `oi`.`product_type`, `oi`.`product_id`, `oi`.`product_name` ;

