INSERT INTO `acs_questions` (`id`, `is_sample`, `strategy_id`, `question_number`, `text`) VALUES
(1, 0, NULL, 1, 'برای اینکه مطلع شوم دیگران در صورت داشتن چنین مشکلی چه‌کار می‌کنند، با افراد دیگر صحبت می‌کنم.'),
