INSERT INTO `aq_questions` (`id`, `question_text`, `factor`, `created_at`, `updated_at`) VALUES
(1, 'گاهی اوقات نمی‌توانم شدت واکنش‌های فیزیکی خود را کنترل کنم.', 'پرخاشگری بدنی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(2, 'در گذشته با کسی درگیر دعوای فیزیکی شده‌ام.', 'پرخاشگری بدنی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(3, 'اگر کسی به من آسیب برساند، ممکن است به او ضربه بزنم.', 'پرخاشگری بدنی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(4, 'اگر عصبانی شوم، ممکن است چیزی را بشکنم.', 'پرخاشگری بدنی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(5, 'گاهی اوقات احساس می‌کنم آماده‌ام تا با کسی دعوا کنم.', 'پرخاشگری بدنی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(6, 'در موقعیت‌های خاص، ممکن است به کسی سیلی بزنم.', 'پرخاشگری بدنی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(7, 'گاهی اوقات از شدت خشم، چیزی را پرت کرده‌ام.', 'پرخاشگری بدنی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(8, 'اگر تحریک شوم، ممکن است به کسی حمله کنم.', 'پرخاشگری بدنی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(9, 'در گذشته از نیروی فیزیکی برای حل اختلاف استفاده کرده‌ام.', 'پرخاشگری بدنی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(10, 'وقتی عصبانی می‌شوم، ممکن است با دیگران بحث کلامی کنم.', 'پرخاشگری کلامی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(11, 'گاهی اوقات فریاد می‌زنم یا داد می‌کشم.', 'پرخاشگری کلامی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(12, 'در بحث‌ها، ممکن است به دیگران توهین کنم.', 'پرخاشگری کلامی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(13, 'وقتی عصبانی هستم، ممکن است حرف‌های تند بزنم.', 'پرخاشگری کلامی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(14, 'گاهی اوقات دیگران را با کلماتم تهدید می‌کنم.', 'پرخاشگری کلامی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(15, 'گاهی اوقات احساس می‌کنم مثل یک بمب ساعتی آماده انفجارم.', 'خشم', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(16, 'به سرعت عصبانی می‌شوم، اما زود هم آرام می‌شوم.', 'خشم', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(17, 'وقتی چیزی مطابق میلم نیست، به شدت عصبانی می‌شوم.', 'خشم', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(18, 'گاهی اوقات بدون دلیل مشخص احساس خشم می‌کنم.', 'خشم', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(19, 'احساس می‌کنم دیگران اغلب باعث عصبانیت من می‌شوند.', 'خشم', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(20, 'وقتی عصبانی می‌شوم، نمی‌توانم به چیز دیگری فکر کنم.', 'خشم', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(21, 'گاهی اوقات خشمم را با بدخلقی نشان می‌دهم.', 'خشم', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(22, 'گاهی اوقات حسادت می‌کنم به موفقیت دیگران.', 'کینه‌ورزی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(23, 'احساس می‌کنم دیگران با من عادلانه رفتار نمی‌کنند.', 'کینه‌ورزی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(24, 'وقتی کسی به من آسیب می‌رساند، سخت می‌توانم او را ببخشم.', 'کینه‌ورزی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(25, 'گاهی اوقات کینه دیگران را در دلم نگه می‌دارم.', 'کینه‌ورزی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(26, 'احساس می‌کنم برخی افراد شایسته بدتر از چیزی هستند که دارند.', 'کینه‌ورزی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(27, 'گاهی اوقات به انتقام گرفتن از دیگران فکر می‌کنم.', 'کینه‌ورزی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(28, 'احساس می‌کنم دیگران اغلب قصد آزار من را دارند.', 'کینه‌ورزی', '2025-07-13 22:32:12', '2025-07-13 22:32:12'),
(29, 'سخت می‌توانم بی‌عدالتی‌ها را فراموش کنم.', 'کینه‌ورزی', '2025-07-13 22:32:12', '2025-07-13 22:32:12');
