INSERT INTO `bdi_questions` (`id`, `question_number`, `options`) VALUES
(1, 1, '{\"0\": \"ناراحت نیستم\", \"1\": \"احساس ناراحتی می‌کنم\", \"2\": \"همیشه ناراحتم\", \"3\": \"نمی‌توانم ناراحتی‌ام را تحمل کنم\"}'),
(2, 2, '{\"0\": \"درباره آینده امیدوارم\", \"1\": \"درباره آینده نگرانم\", \"2\": \"احساس می‌کنم آینده تاریک است\", \"3\": \"فکر می‌کنم آینده‌ای ندارم\"}'),
(3, 3, '{\"0\": \"احساس شکست نمی‌کنم\", \"1\": \"از اشتباهاتم ناراحتم\", \"2\": \"خودم را شکست‌خورده می‌دانم\", \"3\": \"از خودم بدم می‌آید\"}'),
(4, 4, '{\"0\": \"همان رضایت قبلی را دارم\", \"1\": \"چیزها کمتر مرا خوشحال می‌کند\", \"2\": \"از هیچ چیز لذت نمی‌برم\", \"3\": \"همه چیز را بی‌ارزش می‌بینم\"}'),
(5, 5, '{\"0\": \"احساس گناه نمی‌کنم\", \"1\": \"گاهی احساس گناه می‌کنم\", \"2\": \"اغلب احساس گناه می‌کنم\", \"3\": \"همیشه خودم را مقصر می‌دانم\"}'),
(6, 6, '{\"0\": \"خودم را دوست دارم\", \"1\": \"گاهی از خودم ناراضی‌ام\", \"2\": \"اغلب از خودم متنفرم\", \"3\": \"از خودم بیزارم\"}'),
(7, 7, '{\"0\": \"بهتر از همیشه نیستم اما خوبم\", \"1\": \"اعتماد به نفس کمتری دارم\", \"2\": \"به خودم شک دارم\", \"3\": \"اصلاً اعتماد به نفس ندارم\"}'),
(8, 8, '{\"0\": \"مانند همیشه تصمیم می‌گیرم\", \"1\": \"سخت‌تر تصمیم می‌گیرم\", \"2\": \"خیلی سخت تصمیم می‌گیرم\", \"3\": \"نمی‌توانم تصمیم بگیرم\"}'),
(9, 9, '{\"0\": \"مثل همیشه به نظر می‌رسم\", \"1\": \"نگرانم دیگران مرا ضعیف ببینند\", \"2\": \"خودم را زشت می‌بینم\", \"3\": \"خودم را تنفرانگیز می‌دانم\"}'),
(10, 10, '{\"0\": \"مانند گذشته کار می‌کنم\", \"1\": \"کمی کندترم\", \"2\": \"خیلی کندترم\", \"3\": \"نمی‌توانم کار کنم\"}'),
(11, 11, '{\"0\": \"مثل همیشه می‌خوابم\", \"1\": \"کمی کمتر می‌خوابم\", \"2\": \"خیلی کمتر یا بیشتر می‌خوابم\", \"3\": \"اصلاً خواب ندارم یا همیشه خوابم\"}'),
(12, 12, '{\"0\": \"مثل همیشه انرژی دارم\", \"1\": \"کمتر انرژی دارم\", \"2\": \"خیلی خسته‌ام\", \"3\": \"انرژی ندارم\"}'),
(13, 13, '{\"0\": \"اشتهایم خوب است\", \"1\": \"کمی اشتهایم کم شده\", \"2\": \"اشتهایم خیلی کم شده\", \"3\": \"اشتها ندارم\"}'),
(14, 14, '{\"0\": \"وزنم تغییر نکرده\", \"1\": \"کمی وزن کم کرده‌ام\", \"2\": \"خیلی وزن کم کرده‌ام\", \"3\": \"وزن خیلی زیاد یا خیلی کم شده\"}'),
(15, 15, '{\"0\": \"نگران سلامتی نیستم\", \"1\": \"کمی نگرانم\", \"2\": \"خیلی نگران سلامتم\", \"3\": \"فکر می‌کنم بیمارم\"}'),
(16, 16, '{\"0\": \"میل جنسی‌ام مثل قبل است\", \"1\": \"کمی کمتر شده\", \"2\": \"خیلی کمتر شده\", \"3\": \"میل ندارم\"}'),
(17, 17, '{\"0\": \"مثل همیشه با آدم‌ها ارتباط دارم\", \"1\": \"کمتر ارتباط دارم\", \"2\": \"تمایل به انزوا دارم\", \"3\": \"کاملاً منزوی‌ام\"}'),
