(19, 19, '{\"0\": \"همیشه احساس مفید بودن دارم\", \"1\": \"کمتر احساس مفید بودن دارم\", \"2\": \"بی‌فایده‌ام\", \"3\": \"وجودم اضافی‌ست\"}'),
(20, 20, '{\"0\": \"همیشه تمرکز دارم\", \"1\": \"کمی تمرکزم پایین است\", \"2\": \"خیلی سخت تمرکز می‌کنم\", \"3\": \"نمی‌توانم تمرکز کنم\"}'),
(21, 21, '{\"0\": \"مثل گذشته کار می‌کنم\", \"1\": \"کمتر کار می‌کنم\", \"2\": \"خیلی کم کار می‌کنم\", \"3\": \"نمی‌توانم کار کنم\"}');
INSERT INTO `beck_hopelessness_questions` (`id`, `question_text`, `is_positive`, `created_at`, `updated_at`) VALUES
(1, 'من با امید و اشتیاق به آینده نگاه می‌کنم.', 1, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(2, 'بهتر است تسلیم شوم، چون نمی‌توانم اوضاع را برای خودم بهتر کنم.', 0, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(3, 'وقتی اوضاع بد پیش می‌رود، دانستن اینکه این وضعیت همیشگی نیست به من کمک می‌کند.', 1, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(4, 'نمی‌توانم تصور کنم زندگی‌ام در 10 سال آینده چگونه خواهد بود.', 0, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(5, 'من زمان کافی برای انجام کارهایی که بیشتر می‌خواهم دارم.', 1, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(6, 'در آینده، انتظار دارم در چیزهایی که برایم مهم هستند موفق شوم.', 1, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(7, 'آینده‌ام تیره و تار به نظر می‌رسد.', 0, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(8, 'من شانس خاصی دارم و انتظار دارم بیشتر از افراد معمولی چیزهای خوب در زندگی به دست آورم.', 1, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(9, 'هیچ‌وقت چیزی که می‌خواهم به دست نمی‌آورم، پس احمقانه است که بخواهم چیزی بخواهم.', 0, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(10, 'تجربیات گذشته‌ام مرا به خوبی برای آینده آماده کرده‌اند.', 1, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(11, 'همه چیزهایی که می‌توانم برای آینده‌ام پیش‌بینی کنم، فقط چیزهای ناخوشایند هستند.', 0, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(12, 'انتظار ندارم به چیزهایی که واقعاً می‌خواهم برسم.', 0, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(13, 'وقتی به آینده نگاه می‌کنم، انتظار دارم بیشتر خوشحال باشم تا غمگین.', 1, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(14, 'امور برایم خوب پیش نمی‌روند و نمی‌دانم این وضعیت کی تمام خواهد شد.', 0, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(15, 'من اعتماد زیادی به آینده دارم.', 1, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(16, 'چیزهایی که در آینده در انتظارم هستند، ارزش تلاش کردن ندارند.', 0, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(17, 'آینده‌ام پر از امکانات بی‌پایان به نظر می‌رسد.', 1, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(18, 'ممکن است چیزهایی که می‌خواهم به دست آورم، اما باورکردنی نیست که این اتفاق بیفتد.', 0, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(19, 'من امید زیادی به آینده دارم.', 1, '2025-06-27 23:48:30', '2025-06-27 23:48:30'),
(20, 'تلاش‌هایم بی‌فایده هستند، چون به هر حال به چیزی که می‌خواهم نمی‌رسم.', 0, '2025-06-27 23:48:30', '2025-06-27 23:48:30');
