INSERT INTO `blog_posts` (`id`, `user_id`, `title`, `slug`, `image`, `description`, `content`, `disable_comment`, `featured`, `view_count`, `status`, `publish_at`, `created_at`, `updated_at`, `deleted_at`, `keywords`) VALUES
(114, 25, 'تولید سادگی نامفهوم', 'تولید-سادگی-نامفهوم', 'Uploads/blog/65c3516926dc3.jpg', 'متن ساختگی با تولید سادگی نامفهوم از صنعت چاپ و با استفاده از طراحان گرافیک است.', '<p>لورم ایپسوم متن ساختگی با تولید سادگی نامفهوم از صنعت چاپ و با استفاده از طراحان گرافیک است. چاپگرها و متون بلکه روزنامه و مجله در ستون و سطرآنچنان که لازم است و برای شرایط فعلی تکنولوژی مورد نیاز و کاربردهای متنوع با هدف بهبود ابزارهای کاربردی می باشد. کتابهای زیادی در شصت و سه درصد گذشته، حال و آینده شناخت فراوان جامعه و متخصصان را می طلبد تا با نرم افزارها شناخت بیشتری را برای طراحان رایانه ای علی الخصوص طراحان خلاقی و فرهنگ پیشرو در زبان فارسی ایجاد کرد. در این صورت می توان امید داشت که تمام و دشواری موجود در ارائه راهکارها و شرایط سخت تایپ به پایان رسد وزمان مورد نیاز شامل حروفچینی دستاوردهای اصلی و جوابگوی سوالات پیوسته اهل دنیای موجود طراحی اساسا مورد استفاده قرار گیرد.<br></p><p><br></p><h1>لورم ایپسوم </h1><p>متن ساختگی با تولید سادگی نامفهوم از صنعت چاپ و با استفاده از طراحان گرافیک است. چاپگرها و متون بلکه روزنامه و مجله در ستون و سطرآنچنان که لازم است و برای شرایط فعلی تکنولوژی مورد نیاز و کاربردهای متنوع با هدف بهبود ابزارهای کاربردی می باشد. کتابهای زیادی در شصت و سه درصد گذشته، حال و آینده شناخت فراوان جامعه و متخصصان را می طلبد تا با نرم افزارها شناخت بیشتری را برای طراحان رایانه ای علی الخصوص طراحان خلاقی و فرهنگ پیشرو در زبان فارسی ایجاد کرد. در این صورت می توان امید داشت که تمام و دشواری موجود در ارائه راهکارها و شرایط سخت تایپ به پایان رسد وزمان مورد نیاز شامل حروفچینی دستاوردهای اصلی و جوابگوی سوالات پیوسته اهل دنیای موجود طراحی اساسا مورد استفاده قرار گیرد.<br></p><p><br></p><div class=\"se-component se-image-container __se__float-center\"><figure style=\"width: 623px;\"><img src=\"http://192.168.1.13:8000/Uploads/blog/65c351471c4b0.png\" alt=\"\" data-rotate=\"\" data-proportion=\"true\" data-size=\"623px,442px\" data-align=\"center\" data-file-name=\"pet_adoption_4x.png\" data-file-size=\"845870\" data-origin=\",\" style=\"width: 623px; height: 442px;\"></figure></div>', 1, 1, 3, 'publish', '2026-08-14 21:12:50', '2024-02-07 09:46:51', '2026-08-14 21:12:50', '2025-01-26 22:26:50', ''),
(115, NULL, 'تست یاریجو', 'تست-یاریجو', 'Uploads/blog/65c497443b2d9.png', 'تست یاریجو تست یاریجو تست یاریجو تست یاریجو تست یاریجو تست یاریجو', '<h1>تست یاریجو</h1><p><span style=\"color: rgb(85, 85, 85);font-size: 14px\">زیستن در ترس اصلا خوشایند نیست. همان گونه که مونتنی می‌گوید:«چیزی نخواهد گذشت که درد و رنج به سراغم خواهد آمد، و نیازی نیست که با شری به نام ترس آن را جلو بیاندازم و تشدیدش کنم، کسی که از درد و رنج می‌ترسد، پیشاپیش متحمل درد و رنج ترس می‌شود.»</span></p>', 1, 1, 5, 'publish', '2026-08-11 11:04:15', '2024-02-08 08:56:38', '2026-08-11 11:04:15', '2025-01-26 22:26:50', ''),
(116, NULL, 'یاریجو', 'یاریجو', 'Uploads/blog/65c498cd64d00.jpg', 'تست تست یاریجو یاریجو یاریجویاریجو تست تست یاریجو یاریجو یاریجویاریجو', '<h1>پست یاریجو تست</h1><p>تست تست یاریجو یاریجو یاریجویاریجو&nbsp;تست تست یاریجو یاریجو یاریجویاریجو تست تست یاریجو یاریجو یاریجویاریجو.</p><p><br></p><p><span style=\"font-size: 14px;color: rgb(85, 85, 85)\">زیستن در ترس اصلا خوشایند نیست. همان گونه که مونتنی می‌گوید:«چیزی نخواهد گذشت که درد و رنج به سراغم خواهد آمد، و نیازی نیست که با شری به نام ترس آن را جلو بیاندازم و تشدیدش کنم، کسی که از درد و رنج می‌ترسد، پیشاپیش متحمل درد و رنج ترس می‌شود.»</span></p><p><span style=\"font-size: 14px;color: rgb(85, 85, 85)\">زیستن در ترس اصلا خوشایند نیست. همان گونه که مونتنی می‌گوید:«چیزی نخواهد گذشت که درد و رنج به سراغم خواهد آمد، و نیازی نیست که با شری به نام ترس آن را جلو بیاندازم و تشدیدش کنم، کسی که از درد و رنج می‌ترسد، پیشاپیش متحمل درد و رنج ترس می‌شود.»</span></p><p><br></p><p><span style=\"color: rgb(85, 85, 85);font-size: 14px\">زیستن در ترس اصلا خوشایند نیست. همان گونه که مونتنی می‌گوید:«چیزی نخواهد گذشت که درد و رنج به سراغم خواهد آمد، و نیازی نیست که با شری به نام ترس آن را جلو بیاندازم و تشدیدش کنم، کسی که از درد و رنج می‌ترسد، پیشاپیش متحمل درد و رنج ترس می‌شود.»</span></p><div class=\"se-component se-image-container __se__float-left\"><figure><img src=\"http://192.168.1.13:8000/Uploads/blog/65c4989d8ab73.png\" alt=\"\" data-rotate=\"\" data-proportion=\"true\" data-size=\",\" data-align=\"left\" data-percentage=\"auto,auto\" data-file-name=\"post-img.png\" data-file-size=\"184846\" data-origin=\",\" style=\"\"></figure></div><p style=\"text-align: center\"><span style=\"color: rgb(85, 85, 85);font-size: 14px\">​<br></span></p><p><span style=\"color: rgb(85, 85, 85);font-size: 14px\"><br></span></p><p><span style=\"color: rgb(85, 85, 85);font-size: 14px\"><br></span></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', 1, 1, 4, 'publish', '2026-02-27 21:14:05', '2024-02-08 09:03:11', '2026-02-27 21:14:05', '2025-01-26 22:26:50', ''),
(117, NULL, 'پست چهارم', 'پست-چهارم', 'Uploads/blog/65c8ad921e879.png', 'پست چهارم پست چهارم پست چهارم پست چهارم پست چهارم پست چهارم پست چهارم', '<h1>لورم</h1><p>​<span style=\"font-size: 16px\"><span style=\"color: rgb(255, 255, 255);background-color: rgb(153, 204, 255)\">لورم ایپسوم یا طرح‌نما (به انگلیسی: Lorem ipsum) به متنی آزمایشی و بی‌معنی در صنعت چاپ، صفحه‌آرایی و طراحی گرافیک گفته می‌شود. طراح گرافیک از این متن به عنوان عنصری از ترکیب بندی برای پر کردن صفحه و ارایه اولیه شکل ظاهری و کلی طرح سفارش گرفته شده استفاده می نماید، تا از نظر گرافیکی نشانگر چگونگی نوع و اندازه فونت و ظاهر متن باشد. معمولا طراحان گرافیک برای صفحه‌آرایی، نخست از متن‌های آزمایشی و بی‌معنی استفاده می‌کنند تا صرفا به مشتری یا صاحب کار خود نشان دهند که صفحه طراحی یا صفحه بندی شده بعد از اینکه متن در آن قرار گیرد چگونه به نظر می‌رسد و قلم‌ها و اندازه‌بندی‌ها چگونه در نظر گرفته شده‌است. از آنجایی که طراحان عموما نویسنده متن نیستند و وظیفه رعایت حق تکثیر متون را ندارند و در همان حال کار آنها به نوعی وابسته به متن می‌باشد آنها با استفاده از محتویات ساختگی، صفحه گرافیکی خود را صفحه‌آرایی می‌کنند تا مرحله طراحی و صفحه‌بندی را به پایان برند.</span>​</span><br></p>', 1, 1, 0, 'draft', '2024-02-11 11:23:20', '2024-02-11 11:21:44', '2024-02-11 11:23:20', '2024-02-11 11:23:20', ''),
(118, NULL, 'تست پست یاریجو 4', 'تست-پست-یاریجو-4', 'Uploads/blog/677a5ed5b5d35.jpg', 'تست پست یاریجو تست پست یاریجو تست پست یاریجو تست پست یاریجو تست پست یاریجو تست پست یاریجو تست پست یاریجو', '<h1>یاریجو پست تست</h1><p><span style=\"color: rgb(0, 0, 0);font-size: 16px\">لورم ایپسوم یا طرح‌نما (به انگلیسی: Lorem ipsum) به متنی آزمایشی و بی‌معنی در صنعت چاپ، صفحه‌آرایی و طراحی گرافیک گفته می‌شود. طراح گرافیک از این متن به عنوان عنصری از ترکیب بندی برای پر کردن صفحه و ارایه اولیه شکل ظاهری و کلی طرح سفارش گرفته شده استفاده می نماید، تا از نظر گرافیکی نشانگر چگونگی نوع و اندازه فونت و ظاهر متن باشد. معمولا طراحان گرافیک برای صفحه‌آرایی، نخست از متن‌های آزمایشی و بی‌معنی استفاده می‌کنند تا صرفا به مشتری یا صاحب کار خود نشان دهند که صفحه طراحی یا صفحه بندی شده بعد از اینکه متن در آن قرار گیرد چگونه به نظر می‌رسد و قلم‌ها و اندازه‌بندی‌ها چگونه در نظر گرفته شده‌است. از آنجایی که طراحان عموما نویسنده متن نیستند و وظیفه رعایت حق تکثیر متون را ندارند و در همان حال کار آنها به نوعی وابسته به متن می‌باشد آنها با استفاده از محتویات ساختگی، صفحه گرافیکی خود را صفحه‌آرایی می‌کنند تا مرحله طراحی و صفحه‌بندی را به پایان برند.</span><br></p>', 1, 1, 8, 'publish', '2026-08-23 23:42:42', '2024-02-11 11:24:51', '2026-08-23 23:42:42', '2025-01-26 22:26:50', ''),
