INSERT INTO `capt_questions` (`id`, `test_id`, `approach_id`, `question_text`, `created_at`, `updated_at`) VALUES
(1, 1, 1, 'من معتقدم که تغییر رفتارهایم مهم‌ترین راه برای حل مشکلاتم است', '2025-03-09 08:17:56', '2025-03-09 08:17:56'),
(2, 1, 1, 'من دوست دارم راه‌های عملی و مشخص برای بهبود زندگی‌ام یاد بگیرم', '2025-03-09 08:17:56', '2025-03-09 08:17:56'),
(3, 1, 1, 'من فکر می‌کنم پاداش و تنبیه ابزارهای موثری برای تغییر رفتار هستند', '2025-03-09 08:17:56', '2025-03-09 08:17:56'),
(4, 1, 1, 'من در مشاوره، ترجیح می‌دهم روی اهداف مشخص و قابل اندازه‌گیری کار کنم', '2025-03-09 08:17:56', '2025-03-09 08:17:56'),
(5, 1, 1, 'من معتقدم که مشاوره باید به من کمک کند تا عادت‌هایم را تغییر دهم', '2025-03-09 08:17:56', '2025-03-09 08:17:56'),
(6, 1, 1, 'من دوست دارم مهارت‌های جدیدی برای مدیریت رفتارهایم یاد بگیرم', '2025-03-09 08:17:56', '2025-03-09 08:17:56'),
(7, 1, 1, 'من فکر می‌کنم تمرکز روی رفتارهای قابل مشاهده مهم‌تر از احساسات درونی است', '2025-03-09 08:17:56', '2025-03-09 08:17:56'),
(8, 1, 1, 'من معتقدم که تکرار و تمرین می‌تواند به بهبود زندگی‌ام کمک کند', '2025-03-09 08:17:56', '2025-03-09 08:17:56'),
(9, 1, 1, 'من در مشاوره، به دنبال راه‌حل‌های سریع و کاربردی هستم', '2025-03-09 08:17:56', '2025-03-09 08:17:56'),
(10, 1, 1, 'من فکر می‌کنم تغییر محیطم می‌تواند رفتارهایم را بهبود دهد', '2025-03-09 08:17:56', '2025-03-09 08:17:56'),
(11, 1, 1, 'من معتقدم که مشاوره باید به من کمک کند تا رفتارهایم را به صورت مرحله‌ای تغییر دهم', '2025-03-09 08:17:56', '2025-03-09 08:17:56'),
(12, 1, 1, 'من دوست دارم در مشاوره، از تکنیک‌های رفتاری برای کاهش استرس استفاده کنم', '2025-03-09 08:17:56', '2025-03-09 08:17:56'),
(13, 1, 1, 'من فکر می‌کنم مشاوره باید به من کمک کند تا رفتارهایم را در موقعیت‌های خاص مدیریت کنم', '2025-03-09 08:17:56', '2025-03-09 08:17:56'),
(14, 1, 2, 'من معتقدم که افکارم نقش اصلی در احساسات و رفتارهایم دارند', '2025-03-09 08:18:56', '2025-03-09 08:18:56'),
(15, 1, 2, 'من دوست دارم یاد بگیرم چطور افکار منفی‌ام را کنترل کنم', '2025-03-09 08:18:56', '2025-03-09 08:18:56'),
(16, 1, 2, 'من فکر می‌کنم تغییر باورهایم می‌تواند زندگی‌ام را بهتر کند', '2025-03-09 08:18:56', '2025-03-09 08:18:56'),
(17, 1, 2, 'من در مشاوره، ترجیح می‌دهم روی اصلاح الگوهای فکری‌ام کار کنم', '2025-03-09 08:18:56', '2025-03-09 08:18:56'),
(18, 1, 2, 'من معتقدم که شناسایی افکار غیرمنطقی به حل مشکلاتم کمک می‌کند', '2025-03-09 08:18:56', '2025-03-09 08:18:56'),
(19, 1, 2, 'من دوست دارم در مشاوره، روی منطقی‌تر کردن دیدگاه‌هایم تمرکز کنم', '2025-03-09 08:18:56', '2025-03-09 08:18:56'),
(20, 1, 2, 'من فکر می‌کنم آگاهی از افکارم می‌تواند به تصمیم‌گیری بهتر کمک کند', '2025-03-09 08:18:56', '2025-03-09 08:18:56'),
(21, 1, 2, 'من معتقدم که مشاوره باید به من کمک کند تا ذهنم را سازمان‌دهی کنم', '2025-03-09 08:18:56', '2025-03-09 08:18:56'),
(22, 1, 2, 'من دوست دارم راه‌هایی برای کاهش خودانتقادی یاد بگیرم', '2025-03-09 08:18:56', '2025-03-09 08:18:56'),
(23, 1, 2, 'من فکر می‌کنم بررسی افکارم می‌تواند احساساتم را متعادل کند', '2025-03-09 08:18:56', '2025-03-09 08:18:56'),
(24, 1, 2, 'من معتقدم که مشاوره باید به من کمک کند تا الگوهای فکری مخرب را شناسایی کنم', '2025-03-09 08:18:56', '2025-03-09 08:18:56'),
(25, 1, 2, 'من دوست دارم در مشاوره، روی تغییر افکارم برای بهبود روابطم کار کنم', '2025-03-09 08:18:56', '2025-03-09 08:18:56'),
(26, 1, 2, 'من فکر می‌کنم مشاوره باید به من کمک کند تا افکارم را در موقعیت‌های استرس‌زا مدیریت کنم', '2025-03-09 08:18:56', '2025-03-09 08:18:56'),
(27, 1, 3, 'من معتقدم که گذشته‌ام روی رفتارها و احساسات فعلی‌ام تاثیر دارد', '2025-03-09 08:19:09', '2025-03-09 08:19:09'),
(28, 1, 3, 'من دوست دارم بفهمم چرا برخی الگوها در زندگی‌ام تکرار می‌شوند', '2025-03-09 08:19:09', '2025-03-09 08:19:09'),
(29, 1, 3, 'من فکر می‌کنم بررسی روابط گذشته‌ام به شناخت خودم کمک می‌کند', '2025-03-09 08:19:09', '2025-03-09 08:19:09'),
(30, 1, 3, 'من در مشاوره، ترجیح می‌دهم روی تجربیات کودکی‌ام کار کنم', '2025-03-09 08:19:09', '2025-03-09 08:19:09'),
(31, 1, 3, 'من معتقدم که احساسات ناخودآگاهم روی تصمیماتم اثر می‌گذارند', '2025-03-09 08:19:09', '2025-03-09 08:19:09'),
(32, 1, 3, 'من دوست دارم در مشاوره، به ریشه‌های عمیق مشکلاتم پی ببرم', '2025-03-09 08:19:09', '2025-03-09 08:19:09'),
(33, 1, 3, 'من فکر می‌کنم رویاهام می‌توانند چیزهای مهمی درباره خودم نشان دهند', '2025-03-09 08:19:09', '2025-03-09 08:19:09'),
(34, 1, 3, 'من معتقدم که مشاوره باید به من کمک کند تا با گذشته‌ام کنار بیایم', '2025-03-09 08:19:09', '2025-03-09 08:19:09'),
(35, 1, 3, 'من دوست دارم بفهمم که چطور تجربیاتم شخصیتم را شکل داده‌اند', '2025-03-09 08:19:09', '2025-03-09 08:19:09'),
(36, 1, 3, 'من فکر می‌کنم درک تعارض‌های درونی‌ام به آرامشم کمک می‌کند', '2025-03-09 08:19:09', '2025-03-09 08:19:09'),
(37, 1, 3, 'من معتقدم که مشاوره باید به من کمک کند تا احساسات سرکوب‌شده‌ام را کشف کنم', '2025-03-09 08:19:09', '2025-03-09 08:19:09'),
(38, 1, 3, 'من دوست دارم در مشاوره، روی روابطم با افراد مهم زندگی‌ام تمرکز کنم', '2025-03-09 08:19:09', '2025-03-09 08:19:09'),
(39, 1, 4, 'من معتقدم که خودشناسی کلید رشد شخصی من است', '2025-03-09 08:19:21', '2025-03-09 08:19:21'),
(40, 1, 4, 'من دوست دارم روی توسعه توانمندی‌ها و استعدادهایم کار کنم', '2025-03-09 08:19:21', '2025-03-09 08:19:21'),
(41, 1, 4, 'من فکر می‌کنم احساسات و تجربیات ذهنی‌ام ارزشمند هستند', '2025-03-09 08:19:21', '2025-03-09 08:19:21'),
(42, 1, 4, 'من در مشاوره، ترجیح می‌دهم روی کشف معنای زندگی‌ام تمرکز کنم', '2025-03-09 08:19:21', '2025-03-09 08:19:21'),
(43, 1, 4, 'من معتقدم که پذیرش خودم به بهبود زندگی‌ام کمک می‌کند', '2025-03-09 08:19:21', '2025-03-09 08:19:21'),
(44, 1, 4, 'من دوست دارم در مشاوره، به دنبال اهداف شخصی و منحصربه‌فردم باشم', '2025-03-09 08:19:21', '2025-03-09 08:19:21'),
(45, 1, 4, 'من فکر می‌کنم اعتماد به خودم مهم‌تر از توصیه‌های دیگران است', '2025-03-09 08:19:21', '2025-03-09 08:19:21'),
(46, 1, 4, 'من معتقدم که مشاوره باید به من کمک کند تا خود واقعی‌ام را پیدا کنم ', '2025-03-09 08:19:21', '2025-03-09 08:19:21'),
(47, 1, 4, 'من دوست دارم روی رشد درونی و آرامش ذهنم کار کنم', '2025-03-09 08:19:21', '2025-03-09 08:19:21'),
(48, 1, 4, 'من فکر می‌کنم هر فرد توانایی رسیدن به بهترین نسخه خودش را دارد', '2025-03-09 08:19:21', '2025-03-09 08:19:21'),
(49, 1, 4, 'من معتقدم که مشاوره باید به من کمک کند تا احساساتم را به طور کامل تجربه کنم', '2025-03-09 08:19:21', '2025-03-09 08:19:21'),
(50, 1, 4, 'من دوست دارم در مشاوره، روی پذیرش و عشق به خودم تمرکز کنم', '2025-03-09 08:19:21', '2025-03-09 08:19:21');
