INSERT INTO `caq_questions` (`id`, `question_text`, `subscale`, `is_reverse`, `created_at`, `updated_at`) VALUES
(1, 'علاقه من به مردم یا سرگرمی‌ها خیلی زود عوض می‌شود.', 'trait_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(2, 'حتی اگر اشخاص نظر خوبی به من نداشته باشند، آرامش کامل خود را از دست نمی‌دهم.', 'trait_anxiety', 1, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(3, 'قبل از اظهارنظر تأمل می‌کنم تا مطمئن شوم آنچه می‌گویم درست است.', 'trait_anxiety', 1, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(4, 'تمایل دارم خود را به دست احساسات حسادت‌آمیز بسپارم.', 'trait_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(5, 'اگر قرار باشد زندگی‌ام را دوباره از سر بگیرم: الف) آن را به‌گونه‌ای متفاوت سازمان می‌دادم، ب) همین زندگی را می‌خواستم.', 'trait_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(6, 'گاهی بدون دلیل احساس نگرانی و دلشوره می‌کنم.', 'trait_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(7, 'اگر پاسخ نه بشنوم، ناراحت می‌شوم، حتی اگر بدانم آنچه می‌خواهم غیرممکن است.', 'trait_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(8, 'وقتی کاری انجام می‌دهم، بیشتر از دیگران انرژی صرف می‌کنم، چون با اضطراب کار می‌کنم.', 'trait_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(9, 'شیوه‌ای به کار می‌برم که حواس‌پرتی نداشته باشم و جزئیات را فراموش نکنم.', 'trait_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(10, 'موانع و دشواری‌ها هرچه باشد، همیشه پشتکار نشان می‌دهم و اهدافم را دنبال می‌کنم.', 'trait_anxiety', 1, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(11, 'در موقعیت‌های دشوار برانگیخته می‌شوم و راه خود را گم می‌کنم.', 'trait_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(12, 'وقتی خود را در مقابل یک مشکل می‌بینم، همیشه احساس می‌کنم به‌اندازه کافی انرژی دارم.', 'trait_anxiety', 1, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(13, 'گاهی احساس می‌کنم به اجبار و بدون دلیل چیزهایی را می‌شمارم.', 'trait_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(14, 'وقتی به چیزهایی فکر می‌کنم که قبلاً به آنها علاقه‌مند بودم، گاهی حالت اضطراب یا برانگیختگی بیش از حد به من دست می‌دهد.', 'trait_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(15, 'در موقعیت‌های اجتماعی، اغلب احساس راحتی می‌کنم و نگران نیستم.', 'trait_anxiety', 1, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(16, 'گاهی بدون دلیل خاصی احساس ترس می‌کنم.', 'trait_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(17, 'معمولاً در تصمیم‌گیری‌ها به دیگران وابسته‌ام.', 'trait_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(18, 'وقتی تحت فشارم، ضربان قلب یا تنفسم سریع‌تر می‌شود.', 'trait_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(19, 'من به‌راحتی می‌توانم با تغییرات غیرمنتظره کنار بیایم.', 'trait_anxiety', 1, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(20, 'اغلب احساس می‌کنم که دیگران مرا قضاوت می‌کنند.', 'trait_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(21, 'در حال حاضر احساس تنش و بی‌قراری می‌کنم.', 'state_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(22, 'در موقعیت‌های جدید، معمولاً احساس نگرانی می‌کنم.', 'state_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(23, 'وقتی با مشکلی مواجه می‌شوم، فوراً مضطرب می‌شوم.', 'state_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(24, 'در چند هفته اخیر، خوابم مختل شده است (بیش از حد می‌خوابم یا نمی‌توانم بخوابم).', 'state_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(25, 'در حال حاضر، احساس می‌کنم نمی‌توانم آرام باشم.', 'state_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(26, 'اخیراً تمرکز کردن برایم دشوار بوده است.', 'state_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
(27, 'در موقعیت‌های استرس‌زا، احساس می‌کنم کنترل خود را از دست می‌دهم.', 'state_anxiety', 0, '2025-07-09 22:09:33', '2025-07-09 22:09:33'),
