INSERT INTO `cdrisc_questions` (`id`, `question_number`, `text`) VALUES
(1, 1, 'من می‌توانم وقتی که چیزها سخت می‌شود، آنها را مدیریت کنم.'),
(2, 2, 'من می‌توانم به سرعت از موقعیت‌های سخت برگردم.'),
(3, 3, 'وقتی دچار مشکلات شوم، به خودم اعتماد دارم.'),
(4, 4, 'من می‌توانم به خوبی با تغییرات کنار بیایم.'),
(5, 5, 'من می‌توانم فشارهای روانی را تحمل کنم.'),
(6, 6, 'من سختی‌ها را فرصتی برای رشد می‌دانم.'),
(7, 7, 'من با انگیزه و قوی هستم حتی زمانی که همه چیز خراب به نظر می‌رسد.'),
(8, 8, 'من می‌توانم مشکلات را به عنوان بخشی از زندگی بپذیرم.'),
(9, 9, 'من از حمایت دیگران بهره‌مند می‌شوم.'),
(10, 10, 'من قادر به تمرکز و تمرین ذهنی هستم.'),
(11, 11, 'من اعتماد به نفس کافی برای مقابله با مشکلات دارم.'),
(12, 12, 'من مشکلات را با آرامش و منطق حل می‌کنم.'),
(13, 13, 'من احساس قدرت و کنترل بر زندگی خود دارم.'),
(14, 14, 'من نسبت به خودم و توانایی‌هایم مثبت هستم.'),
(15, 15, 'من برای خودم هدف دارم و آن را دنبال می‌کنم.'),
(16, 16, 'من در برابر استرس مقاومت بالایی دارم.'),
(17, 17, 'من می‌توانم احساساتم را مدیریت کنم.'),
(18, 18, 'من احساس می‌کنم که می‌توانم با مشکلات مقابله کنم.'),
(19, 19, 'من به آینده امیدوارم.'),
(20, 20, 'من در شرایط سخت انعطاف‌پذیر هستم.'),
(21, 21, 'من به دنبال راه‌حل‌های خلاقانه برای مشکلات هستم.'),
(22, 22, 'من یاد گرفته‌ام که از تجربیات سخت درس بگیرم.'),
(23, 23, 'من به طور کلی احساس رضایت از زندگی دارم.'),
(24, 24, 'من توانایی تنظیم مجدد اهداف و برنامه‌هایم را دارم.'),
(25, 25, 'من به راحتی نمی‌شکنم و مقاومت می‌کنم.');
