INSERT INTO `emotional_divorce_questions` (`id`, `question`, `created_at`, `updated_at`) VALUES
(1, 'آیا احساس می‌کنید همسرتان دیگر مانند گذشته به شما علاقه‌ای ندارد؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(2, 'آیا احساس می‌کنید همسرتان به نیازهای عاطفی شما بی‌توجه است؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(3, 'آیا گفت‌وگوهای شما بیشتر به مشاجره ختم می‌شود تا همدلی؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(4, 'آیا احساس می‌کنید همسرتان شما را درک نمی‌کند؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(5, 'آیا از صمیمیت عاطفی میان خود و همسرتان رضایت ندارید؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(6, 'آیا احساس می‌کنید رابطه‌تان مانند گذشته شاد و پرانرژی نیست؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(7, 'آیا تمایل به گذراندن زمان با همسرتان کاهش یافته است؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(8, 'آیا از بودن در کنار همسرتان احساس خستگی یا بی‌حوصلگی می‌کنید؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(9, 'آیا حس می‌کنید بیشتر برای بچه‌ها یا خانواده کنار هم هستید تا برای خودتان؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(10, 'آیا در بیشتر مواقع سکوت بین شما غالب است؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(11, 'آیا احساس می‌کنید همسرتان از شما فاصله گرفته است؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(12, 'آیا به جای گفت‌وگو با همسرتان، بیشتر با دیگران درد دل می‌کنید؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(13, 'آیا احساس تنهایی در رابطه‌تان دارید؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(14, 'آیا صمیمیت جنسی شما کاهش چشمگیری یافته است؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(15, 'آیا احساس می‌کنید همسرتان به ظاهر یا رفتار شما اهمیت نمی‌دهد؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(16, 'آیا همسرتان از شما انتقادهای مداوم می‌کند؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(17, 'آیا به آینده رابطه‌تان امیدی ندارید؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(18, 'آیا همسرتان شما را حمایت نمی‌کند؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(19, 'آیا احساس می‌کنید احترام متقابل بین شما از بین رفته است؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(20, 'آیا رفتارهای سرد و بی‌تفاوتی از همسرتان دریافت می‌کنید؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(21, 'آیا از رابطه‌تان بیشتر احساس ناامیدی دارید تا رضایت؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(22, 'آیا احساس می‌کنید دیگر حرف مشترکی با هم ندارید؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(23, 'آیا گاهی به جدایی فکر می‌کنید؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16'),
(24, 'آیا حس می‌کنید از نظر عاطفی دیگر با هم هماهنگ نیستید؟', '2025-04-16 11:12:16', '2025-04-16 11:12:16');
