(1, 1, 1, 'من احساس می‌کنم مردم مهم زندگی‌ام دیر یا زود من را ترک خواهند کرد.'),
(2, 1, 2, 'نمی‌توانم روی محبت یا حمایت دیگران برای مدت طولانی حساب باز کنم.'),
(3, 1, 3, 'دائماً می‌ترسم کسی که دوستش دارم ممکن است بمیرد یا مرا ترک کند.'),
(4, 1, 4, 'احساس می‌کنم همیشه رابطه‌ام با آدم‌های مهم، به‌زودی خراب می‌شود.'),
(5, 1, 5, 'فکر می‌کنم دیگران به من وابسته نمی‌مانند.'),
(6, 2, 6, 'نمی‌توانم به نیت‌های مردم اعتماد کنم.'),
(7, 2, 7, 'اگر احساساتم را نشان دهم، ممکن است علیه من استفاده شود.'),
(8, 2, 8, 'مردم معمولاً از من سوءاستفاده می‌کنند یا به من ضربه می‌زنند.'),
(9, 2, 9, 'به‌ندرت کسی را پیدا می‌کنم که واقعاً به او اعتماد کنم.'),
(10, 2, 10, 'اگر کسی با من خوب باشد، احتمالاً نیت بدی دارد.'),
(11, 3, 11, 'من احساس می‌کنم نیازهای هیجانی من هیچ‌وقت برآورده نمی‌شوند.'),
(12, 3, 12, 'هیچ‌کس واقعاً مرا درک نمی‌کند.'),
(13, 3, 13, 'من کسی را ندارم که واقعاً احساس نزدیکی با او داشته باشم.'),
(14, 3, 14, 'من اغلب احساس تنهایی و سردی می‌کنم.'),
(15, 3, 15, 'هیچ‌کس مرا واقعاً دوست ندارد یا برایم اهمیت قائل نیست.'),
(16, 4, 16, 'من احساس می‌کنم عیبی دارم که دیگران آن را مسخره می‌کنند.'),
(17, 4, 17, 'احساس می‌کنم درونم زشت یا شرم‌آور است.'),
(18, 4, 18, 'از اینکه دیگران واقعاً مرا بشناسند، می‌ترسم.'),
(19, 4, 19, 'همیشه روی آنچه دیگران درباره‌ام فکر می‌کنند حساس هستم.'),
(20, 4, 20, 'فکر می‌کنم کاستی بزرگی دارم.'),
(21, 5, 21, 'احساس می‌کنم با بقیه متفاوت و جدا هستم.'),
(22, 5, 22, 'به ندرت می‌توانم شبیه بقیه باشم.'),
(23, 5, 23, 'من همیشه احساس تنهایی دارم حتی در جمع.'),
(24, 5, 24, 'احساس می‌کنم هیچ‌جا جا ندارم.'),
(25, 5, 25, 'من با آدم‌های دیگر ارتباط نزدیکی ندارم.'),
(26, 6, 26, 'من به دیگران نیاز زیادی دارم تا تصمیماتم را بگیرم.'),
(27, 6, 27, 'نمی‌توانم بدون کمک کسی کارهای زندگی‌ام را پیش ببرم.'),
(28, 6, 28, 'احساس می‌کنم بدون کمک بقیه ناتوانم.'),
(29, 6, 29, 'اگر کسی حمایت نکند، نمی‌توانم پیشرفت کنم.'),
(30, 6, 30, 'احساس می‌کنم بدون تکیه‌گاه دوام ندارم.'),
(31, 7, 31, 'من دائماً از اتفاقات وحشتناک می‌ترسم.'),
(32, 7, 32, 'احساس می‌کنم هر لحظه ممکن است تهدیدی بخورد.'),
(33, 7, 33, 'از خطرهای غیرمنتظره در زندگی می‌ترسم.'),
(34, 7, 34, 'نمی‌توانم تصور کنم که زندگی‌ام ایمن باشد.'),
(35, 7, 35, 'احساس می‌کنم همیشه منتظر حادثه‌ای وحشتناک هستم.'),
(36, 8, 36, 'احساس می‌کنم بدون اینکه زندگی خود را داشته باشم، برای بقیه زندگی می‌کنم.'),
(37, 8, 37, 'من قادر نیستم استقلال عاطفی داشته باشم.'),
(38, 8, 38, 'مدام خودم را با دیگران مقایسه می‌کنم و به آنها وابسته‌ام.'),
(39, 8, 39, 'احساس می‌کنم هویت مشخصی ندارم.'),
(40, 8, 40, 'نیاز دارم دیگران مرا راهنمایی کنند تا احساس کنم هستم.'),
(41, 9, 41, 'احساس می‌کنم هرگز در کاری موفق نمی‌شوم.'),
(42, 9, 42, 'می‌ترسم در زندگی شکست بخورم.'),
(43, 9, 43, 'احساس می‌کنم کمتر از بقیه هستم.'),
(44, 9, 44, 'من در تحقق اهدافم ناموفقم.'),
(45, 9, 45, 'همیشه فکر می‌کنم نمی‌توانم کارهای مهم را انجام دهم.'),
(46, 10, 46, 'من از اِعمال خواسته‌های دیگران می‌ترسم.'),
(47, 10, 47, 'ترجیح می‌دهم حرف سایرین را گوش دهم تا اینکه حرف خودم را بزنم.'),
(48, 10, 48, 'اگر مخالفت کنم، ممکن است طرد شوم.'),
(49, 10, 49, 'قادر نیستم از خواسته‌های درونی‌ام دفاع کنم.'),
(50, 10, 50, 'راضی نیستم با زدن حرفم مشکلات ایجاد کنم.'),
(51, 11, 51, 'من اول نیازهای بقیه را بر نیازهای خودم ترجیح می‌دهم.'),
(52, 11, 52, 'اگر کسی ناراحت باشد، احساس مسئولیت می‌کنم.'),
(53, 11, 53, 'خودم را نادیده می‌گیرم تا دیگران خوشحال باشند.'),
(54, 11, 54, 'اگر نیاز کسی را برآورده نکنم، احساس گناه می‌کنم.'),
(55, 11, 55, 'حدود خودم را حفظ نمی‌کنم تا کسی آسیب نبیند.'),
(56, 12, 56, 'همیشه باید بهترین باشم.'),
(57, 12, 57, 'اگر میانگین باشم، احساس بی‌ارزشی دارم.'),
(58, 12, 58, 'از عدم کمال می‌ترسم.'),
(59, 12, 59, 'درونی انتقاد سختی دارم از خودم.'),
(60, 12, 60, 'اگر نقشی را عالی اجرا نکنم، خودم را سرزنش می‌کنم.'),
(61, 13, 61, 'فکر می‌کنم شایسته برخورد ویژه‌ای هستم.'),
(62, 13, 62, 'انتظار دارم دیگران مرا تحسین کنند.'),
(63, 13, 63, 'حس می‌کنم بیشتر از بقیه لیاقت دارم.'),
(64, 13, 64, 'نمی‌توانم خودم را تنظیم کنم مگر وقتی در مرکز توجه باشم.'),
(65, 13, 65, 'من خاص هستم و باید این حس دیده شود.'),
(66, 14, 66, 'من نمی‌توانم خواسته‌هایم را کنترل کنم.'),
(67, 14, 67, 'قطعا در برابر وسوسه‌ها می‌بازم.'),
(68, 14, 68, 'احساس می‌کنم نظم در زندگی‌ام نیست.'),
(69, 14, 69, 'اگر مقاوم نباشم، کارها خراب می‌شود.'),
(70, 14, 70, 'من انگیزه‌ام ضعیف است و از پسش برنمی‌آیم.'),
(71, 15, 71, 'دنبال اینم که همیشه دیگران مرا دوست داشته باشند.'),
(72, 15, 72, 'تمایل دارم با کسی مخالفت نکنم تا دیگران مرا قبول کنند.'),
(73, 15, 73, 'من نیاز دارم به تصویب دائمی دیگران.'),
(74, 15, 74, 'اگر کسی ناخوشحال شود، از گفتن حقیقت می‌ترسم.'),
(75, 15, 75, 'من برای تایید اجتماعی، واقعاً ارزش قائل‌ام.'),
(76, 16, 76, 'اغلب انتظار بدترین حالت را دارم.'),
(77, 16, 77, 'می‌ترسم شرایط از کنترل من خارج شود.'),
(78, 16, 78, 'نگاه تاریکی به آینده دارم.'),
(79, 16, 79, 'احساس می‌کنم همیشه دارم منتظر فاجعه‌ام.'),
(80, 16, 80, 'تماماً تمرکزم روی مشکلات است نه راه‌حل.'),
(81, 17, 81, 'احساساتم را اغلب پنهان می‌کنم.'),
(82, 17, 82, 'نمی‌توانم آزادانه گریه کنم یا خشمم را نشان دهم.'),
(83, 17, 83, 'اگر یک احساس قوی داشته باشم، نگرانش می‌شوم.'),
(84, 17, 84, 'ترس دارم دیگران احساسات واقعی‌ام را ببینند.'),
(85, 17, 85, 'احساساتم را می‌بلعم تا آرام باشم.'),
(86, 18, 86, 'من فکر می‌کنم اگر اشتباه کنم باید به شدت تنبیهم کنند.'),
(87, 18, 87, 'اگر خطا کنم، خود را بی‌ارزش می‌دانم.'),
(88, 18, 88, 'احساس می‌کنم اگر تنبیه نشوم، آدم ضعیفی هستم.'),
(89, 18, 89, 'انتظار دارم خودم را در مقابل خطاها تنبیه کنم.'),
(90, 18, 90, 'اگر فکر کنم بی‌قصور هستم، احساس گناه شدیدی می‌گیرم.');
