INSERT INTO `gdms_questions` (`id`, `question_text`, `style`, `created_at`, `updated_at`) VALUES
(1, 'من قبل از تصمیم‌گیری، تمام گزینه‌های ممکن را بررسی می‌کنم.', 'rational', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(2, 'من برای تصمیم‌گیری، اطلاعات را به‌صورت سیستماتیک تحلیل می‌کنم.', 'rational', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(3, 'تصمیماتم را بر اساس منطق و استدلال می‌گیرم.', 'rational', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(4, 'من همیشه بهترین گزینه را پس از بررسی دقیق انتخاب می‌کنم.', 'rational', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(5, 'برای تصمیم‌گیری، مزایا و معایب هر گزینه را مقایسه می‌کنم.', 'rational', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(6, 'من به احساسات درونی‌ام برای تصمیم‌گیری اعتماد می‌کنم.', 'intuitive', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(7, 'وقتی تصمیم می‌گیرم، به شهودم توجه زیادی دارم.', 'intuitive', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(8, 'تصمیماتم را بر اساس حس اولیه‌ام می‌گیرم.', 'intuitive', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(9, 'در شرایط پیچیده، به غریزه‌ام اعتماد می‌کنم.', 'intuitive', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(10, 'احساس می‌کنم شهودم در تصمیم‌گیری به من کمک می‌کند.', 'intuitive', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(11, 'قبل از تصمیم‌گیری، با دیگران مشورت می‌کنم.', 'dependent', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(12, 'برای تصمیم‌گیری، به توصیه‌های دیگران نیاز دارم.', 'dependent', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(13, 'ترجیح می‌دهم دیگران در تصمیم‌گیری به من کمک کنند.', 'dependent', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(14, 'از نظرات دیگران برای تصمیم‌گیری استفاده می‌کنم.', 'dependent', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(15, 'احساس می‌کنم برای تصمیم‌گیری به راهنمایی دیگران نیاز دارم.', 'dependent', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(16, 'من تصمیماتم را سریع و بدون تأمل زیاد می‌گیرم.', 'spontaneous', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(17, 'ترجیح می‌دهم تصمیماتم را فوراً بگیرم.', 'spontaneous', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(18, 'وقتی تصمیم می‌گیرم، زیاد فکر نمی‌کنم و سریع عمل می‌کنم.', 'spontaneous', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(19, 'تصمیم‌گیری سریع برایم راحت‌تر است.', 'spontaneous', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(20, 'من معمولاً در لحظه تصمیم می‌گیرم.', 'spontaneous', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(21, 'سعی می‌کنم از تصمیم‌گیری اجتناب کنم.', 'avoidant', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(22, 'تصمیم‌گیری برایم دشوار است و آن را به تعویق می‌اندازم.', 'avoidant', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(23, 'ترجیح می‌دهم دیگران به جای من تصمیم بگیرند.', 'avoidant', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(24, 'وقتی باید تصمیم بگیرم، احساس فشار می‌کنم.', 'avoidant', '2025-07-09 20:17:56', '2025-07-09 20:17:56'),
(25, 'از موقعیت‌هایی که نیاز به تصمیم‌گیری دارند، دوری می‌کنم.', 'avoidant', '2025-07-09 20:17:56', '2025-07-09 20:17:56');
