INSERT INTO `hama_questions` (`id`, `question_number`, `text`) VALUES
(1, 1, 'خلق مضطرب: احساس نگرانی، پیش‌بینی بد، ناتوانی در استراحت، ترس‌های غیرمنطقی'),
