(3, 3, 'ترس‌ها: از تاریکی، غریبه‌ها، تنها بودن، حیوانات، موقعیت‌ها'),
(4, 4, 'بی‌خوابی: مشکل در به خواب رفتن، بیدار شدن در شب، خواب بی‌کیفیت'),
(5, 5, 'مشکلات شناختی: کاهش تمرکز، حافظه ضعیف، مشکل در فکر کردن'),
(6, 6, 'خلق افسرده: عدم لذت، بی‌علاقگی، خستگی، افکار منفی'),
(7, 7, 'علائم جسمی – عضلانی: سفتی، درد عضلانی، اسپاسم'),
(8, 8, 'علائم جسمی – حسی: زنگ زدن گوش، تاری دید، سردرد، کرختی'),
(9, 9, 'علائم قلبی: تپش قلب، درد قفسه سینه، فشار قلبی'),
(10, 10, 'علائم تنفسی: تنگی نفس، احساس خفگی'),
(11, 11, 'علائم گوارشی: سوء هاضمه، تهوع، اسهال، نفخ'),
(12, 12, 'علائم ادراری: تکرر ادرار، سوزش'),
(13, 13, 'علائم خودمختار: تعریق، گرگرفتگی، سرگیجه'),
(14, 14, 'رفتار مشاهده‌شده: بی‌قراری، تکلم سریع، تیک، حرکات غیرارادی');
INSERT INTO `hamilton_anxiety_questions` (`id`, `question_text`, `description`, `created_at`, `updated_at`) VALUES
(1, 'حالت اضطرابی', 'نگرانی‌ها، پیش‌بینی بدترین حالت، ترس و پیش‌بینی خطر، تحریک‌پذیری', '2025-06-27 23:19:40', '2025-06-27 23:19:40'),
(2, 'تنش', 'احساس تنش، خستگی‌پذیری، واکنش‌های ناگهانی، اشک ریختن آسان، لرزش، احساس بی‌قراری، ناتوانی در آرامش', '2025-06-27 23:19:40', '2025-06-27 23:19:40'),
(3, 'ترس‌ها', 'ترس از تاریکی، غریبه‌ها، تنها ماندن، حیوانات، ترافیک، شلوغی', '2025-06-27 23:19:40', '2025-06-27 23:19:40'),
(4, 'بی‌خوابی', 'مشکل در به خواب رفتن، خواب منقطع، خواب غیررضایت‌بخش و خستگی هنگام بیدار شدن، رویاها، کابوس‌ها، وحشت‌های شبانه', '2025-06-27 23:19:40', '2025-06-27 23:19:40'),
(5, 'عملکرد ذهنی', 'مشکل در تمرکز، حافظه ضعیف', '2025-06-27 23:19:40', '2025-06-27 23:19:40'),
(6, 'خلق افسرده', 'از دست دادن علاقه، عدم لذت از سرگرمی‌ها، افسردگی، بیدار شدن زودهنگام، نوسانات روزانه', '2025-06-27 23:19:40', '2025-06-27 23:19:40'),
(7, 'علائم جسمانی (عضلانی)', 'درد و کوفتگی، پرش عضلانی، سفتی عضلات، حرکات ناگهانی عضلانی، دندان‌قروچه، صدای لرزان، افزایش تونوس عضلانی', '2025-06-27 23:19:40', '2025-06-27 23:19:40'),
(8, 'علائم جسمانی (حسی)', 'وزوز گوش، تاری دید، گرگرفتگی یا احساس سرما، احساس ضعف، احساس سوزن‌سوزن شدن', '2025-06-27 23:19:40', '2025-06-27 23:19:40'),
(9, 'علائم قلبی-عروقی', 'تپش قلب، ضربان قلب سریع، درد قفسه سینه، نبض زدن رگ‌ها، احساس غش', '2025-06-27 23:19:40', '2025-06-27 23:19:40'),
(10, 'علائم تنفسی', 'فشار یا انقباض در قفسه سینه، احساس خفگی، آه کشیدن، تنگی نفس', '2025-06-27 23:19:40', '2025-06-27 23:19:40'),
(11, 'علائم گوارشی', 'مشکل در بلع، نفخ، درد شکمی، احساس سوزش، احساس پری شکم، تهوع، استفراغ، شل شدن مدفوع، کاهش وزن، یبوست', '2025-06-27 23:19:40', '2025-06-27 23:19:40'),
(12, 'علائم ادراری-تناسلی', 'تکرر ادرار، فوریت ادرار، قطع شدن قاعدگی، کاهش میل جنسی', '2025-06-27 23:19:40', '2025-06-27 23:19:40'),
(13, 'علائم اتونوم', 'خشکی دهان، گرگرفتگی، رنگ‌پریدگی، تمایل به تعریق، سرگیجه', '2025-06-27 23:19:40', '2025-06-27 23:19:40'),
(14, 'رفتار در مصاحبه', 'بی‌قراری یا قدم زدن، لرزش، اخم کردن، آه کشیدن، رنگ‌پریدگی، بلع مکرر', '2025-06-27 23:19:40', '2025-06-27 23:19:40');
