INSERT INTO `iat_questions` (`id`, `question_text`, `created_at`, `updated_at`) VALUES
(1, 'چقدر بیشتر از آنچه قصد داشتید آنلاین می‌مانید؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(2, 'چقدر کارهای روزمره یا تکالیف خود را به تعویق می‌اندازید تا زمان بیشتری آنلاین باشید؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(3, 'چقدر ترجیح می‌دهید آنلاین باشید تا با دیگران وقت بگذرانید؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(4, 'چقدر به دلیل استفاده از اینترنت، روابط جدیدی با کاربران آنلاین شکل داده‌اید؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(5, 'چقدر دیگران از مدت زمان آنلاین بودن شما شکایت می‌کنند؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(6, 'چقدر به دلیل استفاده از اینترنت، عملکرد تحصیلی یا شغلی شما کاهش یافته است؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(7, 'چقدر قبل از شروع کار، ایمیل یا شبکه‌های اجتماعی خود را چک می‌کنید؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(8, 'چقدر استفاده از اینترنت بر بهره‌وری کاری شما تأثیر منفی گذاشته است؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(9, 'چقدر وقتی کسی مزاحم استفاده شما از اینترنت می‌شود، عصبی یا دفاعی می‌شوید؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(10, 'چقدر به فکر اینترنت هستید، حتی وقتی آفلاین هستید؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(11, 'چقدر خود را در حال فکر کردن به این می‌بینید که «فقط چند دقیقه دیگر آنلاین باشم»؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(12, 'چقدر نگران هستید که بدون اینترنت زندگی خسته‌کننده یا خالی باشد؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(13, 'چقدر وقتی آفلاین هستید، احساس بی‌قراری، بدخلقی یا افسردگی می‌کنید؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(14, 'چقدر به دلیل ورود به اینترنت تا دیروقت، خوابتان مختل شده است؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(15, 'چقدر وقتی آفلاین هستید، به فکر بازگشت به اینترنت هستید؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(16, 'چقدر به خودتان می‌گویید «فقط چند دقیقه دیگر» وقتی آنلاین هستید؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(17, 'چقدر تلاش کرده‌اید زمان آنلاین بودن خود را کاهش دهید، اما موفق نشده‌اید؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(18, 'چقدر سعی می‌کنید مدت زمان آنلاین بودن خود را از دیگران مخفی کنید؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(19, 'چقدر به جای وقت گذراندن با دیگران، آنلاین بودن را انتخاب می‌کنید؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06'),
(20, 'چقدر وقتی آفلاین هستید، احساس افسردگی یا عصبانیت می‌کنید که با بازگشت به اینترنت برطرف می‌شود؟', '2025-07-09 20:25:06', '2025-07-09 20:25:06');
