(17, 'می‌توانم احساساتم را حتی وقتی پیچیده هستند، توصیف کنم.', 'describing', 0, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(18, 'می‌توانم تغییرات بدنی‌ام را با جزئیات توصیف کنم.', 'describing', 0, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(19, 'می‌توانم بوها یا طعم‌ها را به‌خوبی توصیف کنم.', 'describing', 0, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(20, 'می‌توانم آنچه در ذهنم می‌گذرد را به‌وضوح توضیح دهم.', 'describing', 0, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(21, 'وقتی کاری انجام می‌دهم، حواسم پرت چیزهای دیگر می‌شود.', 'acting_with_awareness', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(22, 'وقتی عجله دارم، کارها را بدون توجه انجام می‌دهم.', 'acting_with_awareness', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(23, 'وقتی مشغول کاری هستم، به چیزهای دیگر فکر می‌کنم.', 'acting_with_awareness', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(24, 'به سختی می‌توانم روی یک کار تمرکز کنم.', 'acting_with_awareness', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(25, 'کارهای روزمره‌ام را به‌صورت خودکار و بدون توجه انجام می‌دهم.', 'acting_with_awareness', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(26, 'وقتی چیزی می‌خوانم، حواسم پرت می‌شود و باید دوباره بخوانم.', 'acting_with_awareness', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(27, 'اغلب حواسم به کاری که انجام می‌دهم نیست.', 'acting_with_awareness', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(28, 'کارها را بدون فکر کردن انجام می‌دهم.', 'acting_with_awareness', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(29, 'وقتی مشغول صحبت با کسی هستم، به چیزهای دیگر فکر می‌کنم.', 'acting_with_awareness', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(30, 'کارهایم را بدون توجه به جزئیات انجام می‌دهم.', 'acting_with_awareness', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(31, 'افکارم را به‌عنوان خوب یا بد قضاوت می‌کنم.', 'accepting_without_judgment', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(32, 'احساساتم را به‌عنوان درست یا نادرست ارزیابی می‌کنم.', 'accepting_without_judgment', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(33, 'وقتی احساسات منفی دارم، خودم را سرزنش می‌کنم.', 'accepting_without_judgment', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(34, 'فکر می‌کنم برخی احساساتم نباید وجود داشته باشند.', 'accepting_without_judgment', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(35, 'وقتی عصبانی می‌شوم، فکر می‌کنم نباید این‌طور باشم.', 'accepting_without_judgment', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(36, 'افکار منفی‌ام را غیرمنطقی می‌دانم.', 'accepting_without_judgment', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(37, 'وقتی احساس بدی دارم، فکر می‌کنم چیزی در من اشتباه است.', 'accepting_without_judgment', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(38, 'سعی می‌کنم افکار یا احساسات ناخوشایندم را تغییر دهم.', 'accepting_without_judgment', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47'),
(39, 'وقتی افکارم را قضاوت می‌کنم، احساس گناه می‌کنم.', 'accepting_without_judgment', 1, '2025-06-29 00:45:47', '2025-06-29 00:45:47');
