INSERT INTO `messaging_messages` (`id`, `order`, `message`, `package_id`, `created_at`, `updated_at`, `time`, `day`, `sms`) VALUES
(5, 2, '<p>با یکدیگر مقابله به مثل نکنید،همسرتان را در رده دیگر افراد قرار ندهید، کسی که با شما زندگی میکند نیازمند توجه و علاقه شماست نه  جنگ و بی مهری تان... مهربانی خود را از همسرتان دریغ نکنید حتی اگر عصبانی یا دلسردهستید بهتر است مسأله تان را حل کنید.                </p>', 4, '2025-04-23 21:38:24', '2025-05-18 08:59:20', 'day', 1, 1),
(6, 3, '<p>اجتناب از همسر بدترین راهی است که در مواقع دلخوری می توانید پیش بگیرید.زمانی که دوری را انتخاب میکنید قلب و روح و صمیمیت ازدواجتان را نابود میکنید،شما باید بیشتر از هرکاری به ازدواجتان توجه نشان دهید،زندگی تان را برای هیچ چیزی پیشکش و قربانی نکنید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:14:02', 'day', 2, 1),
(7, 4, '<p>هنگامی که همسرتان ناخشنود است یک عذرخواهی ساده میتواند جراحات بوجود امده را التیام بخشد.قلب شریک زندگی تان را خالی از عشق و محبت رها نکنید،تنها یکدیگر را دارید پس محرومیت را برای هم انتخاب نکنید. محرومیت عاطفی پایه های زندگی را سست و آماده تخریب میکند.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:13:56', 'day', 3, 1),
(8, 5, '<p>اگر اشتباهی را مرتبا تکرار کنید دیگر عذر خواهی به کارتان نمی آید. شما باید اقدامی در جهت رفع مشکل پیش آمده انجام دهید تا شریک زندگی تان متوجه اهمیت خود در زندگی تان بشود.با بی توجهی همسرتان را دلسرد و از خود دور نکنید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:13:49', 'day', 4, 1),
(9, 6, '<p>مراقب کج اندیشی و سوتفاهم های پیش آمده باشید تا با بی فکری ضربه اساسی به پایه های ازدواجتان وارد نکرده اید.رفع هرگونه بداندیشی و سوتفاهم ضرورت اولیه زندگی شماست پس کوتاهی نکنید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:13:41', 'day', 5, 1),
(10, 7, '<p>اگر زندگی را با عشق شروع کرده اید و بعد از مدتی ازدواجتان را بزرگترین اشتباه خود می دانید،باید آگاه باشید که در طول زمان هرگز کار مثبت و سازنده ای در جهت رفع تنش ها و سوتفاهم های بوجود امده نکرده اید. عشق نیاز به مراقبت و نگهداری دارد وگرنه به راحتی در میان اندوه و دلخوری ها دفن می شود.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:13:33', 'day', 6, 1),
(11, 8, '<p>شما و همسرتان باید هرآنچه نیاز دارید از یکدیگر بگیرید. رعایت این اصل ساده باعث تداوم یک ازدواج موفق و سالم می شود.بی توجهی به رفع نیازهای همسرتان ازدواجتان را تبدیل به میدان نبرد می کند که هرکسی برای گرفتن حق خویش می جنگد.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:13:26', 'day', 7, 1),
(12, 9, '<p>برای داشتن یک ازدواج سالم شما باید مهربان ، صادق ، سخاوتمند و با ملاحظه و علاقمند باشید تا بتوانید از پس فراز و نشیب های روابط تان بر بیایید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:13:20', 'day', 8, 1),
(13, 10, '<p>از هرگونه رفتاری که همسرتان را دلسرد یا ناراحت کند پرهیز کنید. اگر در ابتدا حساسیت ها و حد و مرزهایتان را برای یکدیگر مشخص کنیدو بعد از آن به حریم شخصی یکدیگر احترام بگذارید ازدواجی شاد و سالم خواهید داشت البته خطا و اشتباه پیش می آید اما جبران و علاقمندی به رفع مسائل پیش امده همه چیز را حل خواهد کرد.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:13:13', 'day', 9, 1),
(14, 11, '<p>از خود گذشتگی و تلاش برای حفظ رضایت همسر نباید یک طرفه باشد هر دو نفرتان باید در جهت رفع نیازهای یکدیگر بکوشید.اگر یک طرف مرتبا تلاش کند تا هرآنچه نیاز دارید را به شما بدهد اما شما بی توجه به خواسته های همسرتان باشید به مرور زمان شریک زندگی تان را خسته و دلزده خواهید کرد.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:13:06', 'day', 10, 1),
(15, 12, '<p>مهم ترین حالت رضایت و صمیمیت این است که از روابطی که با همسرتان دارید لذت ببرید هر دوی شما به اندازه کافی عشق و احساس به یکدیگر داده باشید. کمبودها علل دعوا و تعارضات زناشویی هستند سعی کنید کمبودی باقی نگذارید اگر یک ازدواج پایدار و سالم می خواهید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:14:21', 'day', 11, 1),
(16, 13, '<p>از خود گذشتگی های زیاد باعث می شود شما دلسرد و متوقع شوید که حالا دیگر نوبت دیگری است که گذشت و ایثار داشته باشد. قانون برابری باید در یک ازدواج سالم برقرار باشد تا هیچ یک از طرفین شاکی و دیگری بی تفاوت و صرفا گیرنده امتیازات مثبت نباشد. روابط دو سویه در در جریان رابطه را به حالت تعادل می رساند.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:14:44', 'day', 12, 1),
(17, 14, '<p>در حالت تعارض و دعوا یادتان باشد هنوز در پیوند و ازدواج هستید بی توجهی و بددهنی به همسرتان شما را در شرایط دردناک تری قرار می دهد. به جای آزار رساندن نیازهای یکدیگر را برطرف کنید کوشش برای دعوا و مجادله را به کوشش برای رفع کمبوهای یکدیگر تغییر دهید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:14:56', 'day', 13, 1),
(18, 15, '<p>به حالت تدافعی فرو نروید از همسرتان فاصله نگیرید طوری رفتار نکنید که نه توجهی بدهید و نه بگیرید رابطه را قطع و دوری را به عادت و تکرار تبدیل نکنید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:15:09', 'day', 14, 1),
(19, 16, '<p>به همان میزان که متوجه و مراقب تاثیر رفتار همسرتان بر زندگی و احساسات خود هستید آیا فکر می کنید که رفتار شما چه تاثیری بر عواطف و روحیات او خواهد داشت؟خودخواهی شما را از یکدیگر دور و صمیمیت را نابود خواهد کرد مراقبت از روحیات همسر وظیفه مهم و موثر در ازدواجی سالم است.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:15:21', 'day', 15, 1),
(20, 17, '<p>در یک ازدواج سالم هیچ یک از طرفین نباید ترس بازگو کردن دیدگاه هایشان را داشته باشند سعی کنید قبل از هر چیزی دوست یکدیگر باشید نه منتقد و باعث سرکوب هم...</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:15:47', 'day', 16, 1),
(21, 18, '<p>هیچ چیزی را تحمل نکنید، تحمل یعنی سرکوب احساسات. بجای تحمل مشکلاتتان را حل و فصل و بازگو کنید و در جهت رفعشان بکوشید. هیچ مسٔله ای را مبهم و حل نشده باقی نگذارید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:16:00', 'day', 17, 1),
(22, 19, '<p>هر خواسته ای از همسرتان دارید محترمانه بیان کنید عشق و احترام در کنار هم معنا پیدا می کنند.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:16:17', 'day', 18, 1),
(23, 20, '<p>تمسخر اعتقادات و افکار همسرتان کاری به دور از ادب و احترام است ، هرگز تحت هیچ شرایطی حتی اگر افکار و اعتقادات همسرتان از نظر شما اشتباه بود نیز دست به مسخره کردن شریک زندگی تان نزنید و او را سرافکنده نکنید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:16:34', 'day', 19, 1),
(24, 21, '<p>اجازه دهید همسرتان دیدگاهش را بیان کند موضع نگیرید و در جهت دفاع از خود تلاش نکنید. زندگی مشترک یعنی سازش ، هیچ کس قرار نیست برنده بازی باشد چون این زندگی شماست نه بازی ...</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:17:03', 'day', 20, 1),
(25, 22, '<p>در یک ازدواج سالم هیچ یک از زوجین دیگری را وادار به انجام کاری نمی کنند. آزادی حق تمام انسان ها است.بدلیل اینکه کسی با شما پیوند ازدواج بسته او را به زندانی خود تبدیل نکنید. اجازه دهید همسرتان خودش باشد و آزادی های فردی اش را از او سلب نکنید، اما توجه داشته باشید این آزادی به معنای زیر پا گذاشتن چارچوب های زندگی مشترک نیست.                </p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:17:23', 'day', 21, 1),
(26, 23, '<p>یکی از بزرگترین  نشانه های ازدواج سالم این است که زن و مرد در همه ی امور زندگی با هم برابر هستند و برابر رفتار می کنند. نظر و وجود هیچ یک برتر از دیگری نیست برابری اصل و اساس یک رابطه ی سالم است.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:17:36', 'day', 22, 1),
(27, 24, '<p>به اعتقادات و ارزش های یکدیگر احترام بگذارید . نباید به هیچ طریق انتقاد غیر محترمانه را به دیگری روا دارید یا تحمل کنید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:17:48', 'day', 23, 1),
(28, 25, '<p>هرگونه سوتفاهم و دلخوری را سریع رفع کنید اجازه ندهید دیوار دلخوری بین تان فاصله بیندازد . در جهت مجاب کردن شریک زندگی تان بکوشید و هیچ تلاشی را دریغ نکنید تا سردی و فاصله در رابطه شما سایه نیفکند.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:18:01', 'day', 24, 1),
(29, 26, '<p>هرگونه بدرفتاری اعم از بی تفاوتی ،بی احترامی ، خشونت های کلامی و فیزیکی نباید در رابطه شما وجود داشته باشد . رنجانیدن و اسیب زدن به همسر برای فروکش کردن خشم برانگیخته شما کاری است نابخشودنی . کنترل فردی تان را تقویت کنید و با گفتگوی سالم مشکلات پیش آمده را حل کنید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:18:18', 'day', 25, 1),
(30, 27, '<p>خشم و نفرت دلسردی و دوری می آورد ،آغوش شما برای همسرتان باید امن ترین مکان دنیا باشد این آرامش و امنیت را از همسرتان دریغ نکنید.بهترین هدیه آرامش و امنیت دادن به شریک عاطفی تان است .                </p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:18:33', 'day', 26, 1),
(31, 28, '<p>خشم صلح و آشتی به زندگی شما نمی آورد بلکه فاصله گرفتن و نفرت را در رابطه شما عادی و ریشه ی اعتماد به زندگی تان را می خشکاند. خشم جایی در زندگی اجتماعی ما نباید داشته باشد مهارت های کنترل خشم را یاد بگیرید تا رابطه ی سالم و همیشگی داشته باشید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:20:17', 'day', 27, 1),
(32, 29, '<p>یکدیگر را به دلیل دلخوری و یا ناراحتی های شخصی تان مجازات نکنید. هیچ کس مسئول مسائل پیش آمده در زندگی شما نیست . به دلیل عدم توانایی در کنترل اعصابتان دیگری را مورد آزار و خشونت خواهی خود قرار ندهید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:20:38', 'day', 28, 1),
(33, 30, '<p>یکدیگر را به دلیل دلخوری و یا ناراحتی های شخصی تان مجازات نکنید. هیچ کس مسئول مسائل پیش آمده در زندگی شما نیست . به دلیل عدم توانایی در کنترل اعصابتان دیگری را مورد آزار و خشونت خواهی خود قرار ندهید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:21:27', 'day', 29, 1),
(34, 31, '<p>شرایطی که شما در خشمگین می کند را شناسایی کنید و با توافق یکدیگر شرایطی جایگذین برای مسائل پیش آمده طرح ریزی کنید. تا از بروز رفتارهای آسیب زننده پیشگیری شود.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:21:42', 'day', 30, 1),
(35, 32, '<p>اگر می خواهید در نظر همسرتان خوب و مقبول بنظر برسید از تظاهر به آنچه نیستید و نمی خواهید باشید اجتناب کنید . صداقت در رفتار و گفتار تان است که باعث می شود در نظر شریک زندگی تان جذاب بنظر برسید.اجازه دهید واقعیت ها گویای همه چیز باشند. خوب بودن براحتی قابل تشخیص است و احتیاجی به تلاش برای دیده شدن نیست.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:22:03', 'day', 31, 1),
(36, 33, '<p>واکنش های عاطفی مثبت را به همسرتان به شکلی منطقی و صحیح نشان دهید بروز درست احساسات در روابط عمر رابطه را طولانی و دوام ازدواج را زیاد می کند.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:22:16', 'day', 32, 1),
(37, 34, '<p>یک توضیح مختصر در رابطه با اتفاقات و احساسات تان در طول روز به همسرتان باععث می شود او از تمامی آنچه بر شما گذشته است اطلاع داشته باشد . چه مثبت و چه منفی خود را برای همسرتان آشکار کنید با این کار او را به خود و زندگی تان مطمئن تر می کنید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:22:35', 'day', 33, 1),
(38, 35, '<p>هیچ کاری را بدون کسب رضایت از یکدیگر انجام ندهید تا زمانی که یکی از شما رضایت ندارد کاری را آغاز نکنید. تلاش در جهت جلب رضایت همسر نقش حساس و مهمی در رابطه دارد که نباید از آن غافل شوید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:23:05', 'day', 34, 1),
(39, 36, '<p>در یک ازدواج سالم رمز و رازهای دو نفره و صمیمیت و خلوت های خصوصی زیادی وجود دارد.درباره یکدیگر کنجکاو باشید...</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:23:54', 'day', 35, 1),
(40, 37, '<p>آگاه باشید که صادق نبودن با همسرتان چه اندازه به رابطه و اعتماد بین تان صدمه می زند. از خود بپرسید که آیا تمایل دارید با همسرتان صادق باشید؟ پاسخ به این پرسش میزان مسولیت پذیری و علاقه تان به تعهد را نشان میدهد.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:24:17', 'day', 36, 1),
(41, 38, '<p>تصور نکنید که اگر رفتار عمدی باعث ناراحتی همسرتان میشود از شما سر بزند باید عذر بخواهید و جبران کنید در زندگی مشترک هر نوع رفتار عمدی و غیرعمدی که باعث رنجش طرفین باشد باید مورد توجه و اهمیت قرار بگیرد. عمد نبودن رفتارتان اعمالتان را توجیه نمیکند.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:24:34', 'day', 37, 1),
(42, 39, '<p>چه عادت های آزار دهنده ای دارید؟آیا عادت های ناپسندتان را می شناسید؟ همین حالا لیستی از عادتهای ناپسندتان را یادداشت کنید و در جهت حل و رفعشان بکوشید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:24:50', 'day', 38, 1),
(43, 40, '<p>هرگز طوری رفتار نکنید که انگار طرف مقابلتان وجود خارجی ندارد . خودخواهی ریشه پیوندتان را به آتش میکشد. رفتارهای خودسرانه با استقلال فردی تفاوت های بسیاری دارد.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:25:06', 'day', 39, 1),
(44, 41, '<p>تحت هر شرایطی همسرتان را حمایت کنید و به علایق هم احترام بگذارید. اجازه دهید همسرتان زندگی دلخواهش را در کنار شما تجربه کندو محروم ساختن یکدیگر از خواسته های قلبی بی عدالتی و خودخواهی محض است . با برتری جویی و تحکم پیوندتان را نابود میکنید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:25:21', 'day', 40, 1),
(45, 42, '<p>همیشه آمادگی برای حل و فصل بحران های احتمالی زندگی داشته باشید. حل سریع تعارضات پیش آمده باعث میشود دلخوری فرصت ایجاد فاصله و دلسردی را پیدا نکند.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:25:35', 'day', 41, 1),
(46, 43, '<p>اولویت اصلی در ازدواج همسرتان است. اولویت اول را به شریک زندگی تان بدهید. همسر شما بعد از ازدواج بهترین و مهم ترین دوست و قوم خویش شما خواهد بود.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:25:53', 'day', 42, 1),
(47, 44, '<p>همسرتان را فدای کار و مشغولیت های ذهنی خود نکنید توقع مالی اضافی یا به خدمت گرفتن همسر در جهت کسب رضایت خویش عشق بین تان را کمرنگ میکند همه چیز بعد از ازدواج در خدمت رابطه شما باید باشد نه هیچکدام از شما در خدمت یکدیگر.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:26:23', 'day', 43, 1),
(48, 45, '<p>کاری کنید همه چیز چه مثبت و چه منفی زندگی را در جهت بهتر شدن و سازندگی سوق بدهد نه تخریب و ویرانگری . این که ازدواجتان به چه سمتی برود انتخاب شماست.مثبت یا منفی؟</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:26:48', 'day', 44, 1),
(49, 46, '<p>با یکدیگر توافق کنید که اوقات فراغت خود را چگونه بگذرانید. هر هفته برنامه ای مناسب با شرایط زندگی تان بچینید تا رابطه را از روزمرگی و تکرار نجات دهید . سیاست پیش گرفتن تفاهم از بسیاری از تعارضات احتمالی در زندگی مشترک می کاهد.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:27:18', 'day', 45, 1),
(50, 47, '<p>برنامه کاری خود را طوری تنظیم کنید که به اوقات دو نفرتان آسیب وارد نکند ، اگر دچار کمبود وقت هستید برنامه های شغلی تان را اصلاح کنید . یادتان باشد ازدواج و رابطه تان با انسانی دیگر ازرش بیشتری نسبت به شغل و کارتان دارد . عشق را قربانی هیچ چیزی نکنید اگر خواهان ازدواجی سالم و شاد هستید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:27:44', 'day', 46, 1),
(51, 48, '<p>اگر در مسئله ای حق با هر دوی شماست سعی کنید به تفاهم برسید که رضایت هر دو جلب شود . هرگز یک طرف را ناراضی رها نکنید . اولویت و اهمیت را به دیگری بدهید تا تعادل در زندگی برقرار شود.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:28:04', 'day', 47, 1),
(52, 49, '<p>به همسرتان نشان دهید که بهترین اوقات را در کنارش سپری میکنید و با او شاد هستید ، با این کار امنیت را به او هدیه میدهید ازدواج سالم یعنی رفتار سالم با ازدواج تان...</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:28:50', 'day', 48, 1),
(53, 50, '<p>هرگز بخاطر فرزندتان با یکدیگر بحث و مشاجره نکنید . بهترین موهبت که میتوانید به فرزندتان هدیه دهید عشق است . بخاطر داشته باشید که عشق است که فرزندانتات را سالم رشد میدهد نه دعوا و مشاجره.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:29:06', 'day', 49, 1),
(54, 51, '<p>هر تصمیم و یا هر گونه اقدامی  برای فرزندانتان اعمال میکنید باید با توافق و رضایت هردوی شما باشد. هرگز هیچ کدامتان را در مقابل فرزند خود کوچک و بی اثر نکنید . به فرزند خود احترام و تفاهم را بیاموزید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:29:50', 'day', 50, 1),
(55, 52, '<p>بیشترین بها و ارزش را به احساسات و رضایت همسرتان بدهید. به همان میزان که به کار و فرزند و اقوام خود تعهد دارید در برابر شریک عاطفی تان نیز مسئولید.احساس بی ارزشی و کمرنگ بودن را لایق همسر خود ندانید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:30:14', 'day', 51, 1),
(56, 53, '<p>شدید ترین و مهم ترین نیاز عاطفی همسرتان را می شناسید؟ توجه به نیازهای عاطفی یکدیگر شما را به یکدیگر نزدیک و صمیمی میکند.یک برنامه برای ایجاد صمیمیت بیشتر را در روزمره خود جای دهید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:30:33', 'day', 52, 1),
(57, 54, '<p>تفاهم و سازگاری بوجود آمدنی است . اگر در زندگی تفاهم ندارید بدانید که اولویت را به رابطه خود نداده اید. فداکاری ،گذشت ، توجه و حس امنیت دادن رابطه خراب و پایان یافته و مرده را احیا و بازسازی میکند.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:31:07', 'day', 53, 1),
(58, 55, '<p>با تمام وجود به همسر تان عشق بورزید و توجه کنید تا شاهد به ثمر نشستن تلاش هایتان باشید. عشق و محبت هرگز نفرت و دلسردی بوجود نمی آورد . هر چه بدهید همان را دریافت می کنید.</p>', 4, '2025-04-23 21:38:24', '2025-05-18 09:31:31', 'day', 54, 1),
(60, 1, '<p>اگر با اعتماد به نفس تر از الان خود بودم چگونه رفتار می کردم؟یک لیست از تفاوت های رفتار اکنون و رفتار با اعتماد بنفس بنویسید و در ذهنتان مقایسه کنید تا از مسیری که قرار است طی کنید اگاه شوید.                </p>', 6, '2025-04-23 21:38:24', '2025-05-18 11:10:19', 'day', 1, 1),
(61, 2, '<p>اگر اعتماد بنفسم را تقویت کنم در نوع رفتارم با دیگران چه تفاوتی ایجاد می شود؟(۵ مورد از تفاوتها را یادداشت کنید)</p>', 6, '2025-04-23 21:38:24', '2025-05-18 11:10:37', 'day', 2, 1),
(62, 3, '<p>چه توانمندی هایی را باید در خود تقویت کنم؟ بعنوان مثال مقایسه نکردن خود با دیگران، نترسیدن از انجام کارهای درست، نگران قضاوت های دیگران نبودن و ... رفتار سازنده : مطمئن بودن به خود، افزایش قدرت ریسک پذیری ، گام برداشتن در جهت کسب رضایت از خود و ...</p>', 6, '2025-04-23 21:38:24', '2025-05-18 11:11:09', 'day', 3, 1),
(63, 4, 'در محیط کار یا تحصیل چگونه رفتاری می توانم داشته باشم؟\r\nگام برداشتن در جهت افزایش مهارت های درسی یا کاری\r\nابراز وجود و منزوی نبودن \r\nارائه پیشنهاد برای توسعه کار \r\n', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(64, 5, 'یک کتاب درباره افزایش اعتماد بنفس و راهکارهای ابراز وجود مطالعه کنید . (روزانه پنج صفحه)', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(65, 6, 'اولین گام برای ایجاد استقلال فردی تان چه می تواند باشد؟\r\nایجاد نظم و برنامه ریزی \r\nالگوی شخصیتی و شرایط زندگی تان را در تصمیم گیری در نظر بگیرید.\r\nاز تصمیم های ساده و کوچک شروع کنید.', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(66, 7, 'تسلیم ترس های خود نشوید . برای شناخت خود وقت بگذارید و ترس های تان را شناسایی کنید. این کار به شما کمک میکند تا خود را با محدودیت هایی که تر س های تان بوجود می اورند اشنا باشید تا براحتی مچ ضعف های خودتان را بگیرید. شناخت به شما قدرت انتخاب سازنده و موثر تری میبخشد.(ترس های خود را یادداشت کنید)', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(67, 8, 'گاهی توقعات افراطی یا کمال گرایی باعث میشود شما در دام ترس از اشتباه بیفتید.مراقب سطح توقعات و انتظارات تان از خود باشید.', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(68, 9, 'باورهای محدود کننده را بشناسید : باور اشتباه من به اندازه کافی خوب نیستم.\r\nمن احمق تر از آن هستم که اینکار را بتوانم انجام بدهم.\r\nمن پول کافی برای شروع ندارم.\r\nمن نمیتوانم به خوبی دیگران این کار را انجام دهم.\r\n', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(69, 10, '<p>در هر موقعیتی هستید مهارت های تان را تقویت کنید . در مرحله دوم بر اساس مهارت های تقویت شده تان برنامه ریزی کنید.در نهایت یک ارزیابی دقیق داشته باشید تا میزان خطا  را تا جایی که میتوانید کاهش دهید و مرحله اخر نتیجه گیری تان را به هدف تبدیل کنید.</p>', 6, '2025-04-23 21:38:24', '2025-05-18 11:11:49', 'day', 0, 0),
(70, 11, 'بخاطر داشته باشید اگر کار همیشگی تان را انجام دهید همان نتیجه همیشگی را بدست خواهید اورد.', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(71, 12, 'کمبود مهارت کافی و یا کم تجربگی باعث می شود شما جراتمندانه رفتار نکنید . یک تصمیم ساده که باعث میشود جراتمندانه تر رفتار کنید چیست؟', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(72, 13, 'گام اول تعهد به خود است. به خود قود بدهید متفاوت عمل کنید . ای بار تا اخرین مرحله پیش بروید . حرف های بی فایده و بازدارنده ذهنتان را شناسایی کنید.', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(73, 14, '   ممکن است ذهنتان از روی ترس و برای حفظ آسایش و یکنواختی همیشگی تان به شما اعتراض کند . \r\n(این بار هم مثل همیشه است،این کارها فایده ای ندارد،تو از عهده این کار سخت بر نمی آیی ، دیگر دیر شده است ) \r\nاین واکنش ها طبیعی هستند فقط بع آنها گوش کنید اجازه دهید این حمله صورت بگیرد. بعد به سراغ کارهایتان بروید.استمرار شرط موفقیت شماست.                 ', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(74, 15, 'از ناامید شدن و شکست نترسید.دوباره شروع کنید.یک بار قرار است موفق شوید پس به امتحانش می ارزد. همین حالا یک قدم کوچک بردارید.شروع دوباره ممکن است آخرین تلاشتان در جهت رسیدن به آنچه میخواهید باشد.به راحتی دست برندارید.', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(75, 16, 'برای امروز انتخاب شما کدام است؟تلاش؟یا تسلیم؟', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(76, 17, '                    افکا مزاحمی که مانع پیشروی شما میشود را یادداشت کنید.(الان وقتش نیست ، الان کار مهمتری داری ، حوصله ندارم ، شرایط من با دیگران فرق دارد و....)   نوشتن افکار مزاحم به شما این امکان را میدهد تا بار دیگگر در قلاب افکارتان گیر نیفتید. شکار نشدن توسط افکار مزاحم اواین گام برای یک شروع مستمر است...             ', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(77, 18, 'امروز روز بهانه تراشی ممنوع است.فقط یک قدم به جلو بدون هیچ عذر و بهانه ای. مطمئن باش برای برداشتن این گام های کوچک بزودی به خودت افتخار خواهی کرد.پس همین حالا انجامش بده.', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(78, 19, 'اهدافی که باعث ارتقا کیفیت زندگی تان میشود را یادداشت کنید.( حداقل پنج مورد)', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(79, 20, '«انتخاب اوین هدف»\r\nامروز روز خرد کردن اهدافتان است.هرچه بیشتر خردش کنید زودتر تمام می شود.!!', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(80, 21, 'چگونه انسانی می خواهی باشی ؟زندگی دلخواهت چگونه است؟ جواب سوال را یادداشت کن . خب قدم بعدی خرد کردن آنهاست...', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(81, 22, '«مانع زدایی»\r\nامروز روز مانع زدایی است. قرار نیست با موانع سر راهت بجنگی فقط باید نادیده بگیری. زمان شروع هر کاری به هیچ چیز جز انجام کار مورد نظر فکر نکن.(فقط امروز کار سختی نیست درست است؟)', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(82, 23, 'تو در هیچ مسابقه ای نیستی!! اینجا در جایگاهی که هستی بالاتر و بهتری و تواناتری وجود ندارد. آنچه که هستی را بپذیر. بدون مقایسه. بدون سرکوب خویش. یک گام بدون مقایسه بردار... ', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(83, 24, 'غیر ممکنی وجود ندارد. این فقط یک تصور ذهنی است که از موانع سخن می گوید. پذیرش موانع یعنی در جا زدن. غیر ممکن را رها کن. یک راه پیدا می شود که آنچه را میخواهی بدست آوری. پیدا کردن یک راه حل در این دنیای بزرگ کار راحتی است مگر نه؟!', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(84, 25, 'عادی بودن افکار منفی را بپذیرید. شما کسی را در اطرافتان میشناسید که افکار منفی و سرزنشگر نداشته باشد؟! شما تنها نسان روی زمین نیستید که درگیر افکار ازاردهنده و سرزنشگر است. افکار منفی تان  پذیرا باشید اما آنها را در زندگی اجرا نکنید. فقط شنوده باشید.تا دست کشیدن شما را منزوی و شرمسار از خویش نسازد.', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(85, 26, 'یک کار که در انجام آن بهترین هستید را یادداشت کنید.چگونه می توانید یک کار دیگر را مانند این انجام دهید.(۵ دقیقه زمان بگذارید و یک کار را انتخاب کنید)', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(86, 27, 'پنج مورد از افکاری که ارزشمند نیست و کمکی به رشد شما نمی کند را یادداشت کنید. چشمانتان را ببندید و تصور کنید اگر هر کدام از این پنج عامل نبود چه تفاوتی در چرخه ی زندگی تان ایجاد می شد.', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
(87, 28, 'امتحان کردن تنها را اثبات به خود است.مطمئن باشید نتیجه شما را شگفت زده خواهد کرد.', 6, '2025-04-23 21:38:24', '2025-04-23 21:38:24', 'day', 0, 0),
