INSERT INTO `penn_state_worry_questions` (`id`, `question_text`, `is_reverse_scored`, `created_at`, `updated_at`) VALUES
(1, 'اگر چیزی را شروع نکنم، به این دلیل است که فکر می‌کنم به اندازه کافی خوب انجامش نخواهم داد.', 1, '2025-06-27 23:37:28', '2025-06-27 23:37:28'),
(2, 'نگرانی‌های من به حدی است که گاهی فکر می‌کنم از کنترل خارج شده‌اند.', 0, '2025-06-27 23:37:28', '2025-06-27 23:37:28'),
(3, 'من اصلاً آدم نگرانی نیستم.', 1, '2025-06-27 23:37:28', '2025-06-27 23:37:28'),
(4, 'بسیاری از چیزهایی که نگرانشان هستم، اغلب بی‌اهمیت به نظر می‌رسند.', 0, '2025-06-27 23:37:28', '2025-06-27 23:37:28'),
(5, 'وقتی نگرانم، نمی‌توانم به چیز دیگری فکر کنم.', 0, '2025-06-27 23:37:28', '2025-06-27 23:37:28'),
(6, 'من همیشه نگران چیزی هستم.', 0, '2025-06-27 23:37:28', '2025-06-27 23:37:28'),
(7, 'اغلب به چیزهایی فکر می‌کنم که ممکن است اشتباه پیش بروند.', 0, '2025-06-27 23:37:28', '2025-06-27 23:37:28'),
(8, 'به ندرت نگران چیزی می‌شوم.', 1, '2025-06-27 23:37:28', '2025-06-27 23:37:28'),
(9, 'وقتی نگران چیزی می‌شوم، نمی‌توانم آن را از ذهنم بیرون کنم.', 0, '2025-06-27 23:37:28', '2025-06-27 23:37:28'),
(10, 'وقتی تحت فشار هستم، بیش از حد نگران می‌شوم.', 0, '2025-06-27 23:37:28', '2025-06-27 23:37:28'),
(11, 'اغلب نگران چیزهایی هستم که دیگران اصلاً نگرانشان نمی‌شوند.', 0, '2025-06-27 23:37:28', '2025-06-27 23:37:28'),
(12, 'من به خاطر نگرانی‌هایم، خودم را آزار می‌دهم.', 0, '2025-06-27 23:37:28', '2025-06-27 23:37:28'),
(13, 'معمولاً برای چیزهای کوچک نگران نمی‌شوم.', 1, '2025-06-27 23:37:28', '2025-06-27 23:37:28'),
(14, 'وقتی استرس دارم، نگران شدن برایم آسان‌تر از دیگران است.', 0, '2025-06-27 23:37:28', '2025-06-27 23:37:28'),
(15, 'می‌دانم که نباید نگران باشم، اما نمی‌توانم جلوی خودم را بگیرم.', 0, '2025-06-27 23:37:28', '2025-06-27 23:37:28'),
(16, 'وقتی نگران می‌شوم، فکر کردن به آن برایم سخت است و نمی‌توانم آن را کنار بگذارم.', 0, '2025-06-27 23:37:28', '2025-06-27 23:37:28');
