INSERT INTO `raas_questions` (`id`, `question_text`, `subscale`, `is_reverse`, `created_at`, `updated_at`) VALUES
(1, 'برای من راحت است که با دیگران صمیمی شوم.', 'نزدیک بودن', 0, '2025-07-14 09:25:10', '2025-07-14 09:25:10'),
(2, 'اغلب نگرانم که شریک عاطفی‌ام واقعاً مرا دوست نداشته باشد.', 'اضطراب', 1, '2025-07-14 09:25:10', '2025-07-14 09:25:10'),
(3, 'برایم سخت است که به دیگران اجازه دهم به من وابسته شوند.', 'وابستگی', 1, '2025-07-14 09:25:10', '2025-07-14 09:25:10'),
(4, 'اغلب نگرانم که شریک عاطفی‌ام نخواهد با من بماند.', 'اضطراب', 0, '2025-07-14 09:25:10', '2025-07-14 09:25:10'),
(5, 'وقتی احساساتم را به دیگران نشان می‌دهم، می‌ترسم که آن‌ها همان احساس را به من نداشته باشند.', 'اضطراب', 0, '2025-07-14 09:25:10', '2025-07-14 09:25:10'),
(6, 'برایم راحت است که به دیگران وابسته شوم.', 'وابستگی', 0, '2025-07-14 09:25:10', '2025-07-14 09:25:10'),
(7, 'برایم نسبتاً آسان است که با دیگران صمیمی شوم.', 'نزدیک بودن', 0, '2025-07-14 09:25:10', '2025-07-14 09:25:10'),
(8, 'دیگران اغلب نمی‌خواهند به اندازه‌ای که من دوست دارم صمیمی شوند.', 'وابستگی', 1, '2025-07-14 09:25:10', '2025-07-14 09:25:10'),
(9, 'گاهی اوقات نگرانم که دیگران به من بیش از حد نزدیک شوند.', 'نزدیک بودن', 1, '2025-07-14 09:25:10', '2025-07-14 09:25:10'),
(10, 'اغلب فکر می‌کنم که شریک عاطفی‌ام واقعاً به من اهمیت نمی‌دهد.', 'اضطراب', 0, '2025-07-14 09:25:10', '2025-07-14 09:25:10'),
(11, 'نگرانم که اگر به شریک عاطفی‌ام نیاز داشته باشم، او در دسترس نباشد.', 'اضطراب', 0, '2025-07-14 09:25:10', '2025-07-14 09:25:10'),
(12, 'برایم راحت است که روابط صمیمی با دیگران ایجاد کنم.', 'نزدیک بودن', 0, '2025-07-14 09:25:10', '2025-07-14 09:25:10'),
(13, 'وقتی کسی از نظر عاطفی به من خیلی نزدیک می‌شود، احساس ناراحتی می‌کنم.', 'نزدیک بودن', 1, '2025-07-14 09:25:10', '2025-07-14 09:25:10'),
(14, 'می‌دانم که دیگران وقتی به آن‌ها نیاز دارم در کنارم خواهند بود.', 'وابستگی', 0, '2025-07-14 09:25:10', '2025-07-14 09:25:10'),
(15, 'دیگران وقتی به آن‌ها نیاز دارم، در دسترس نیستند.', 'وابستگی', 1, '2025-07-14 09:25:10', '2025-07-14 09:25:10'),
(16, 'برایم راحت است که دیگران به من وابسته باشند.', 'وابستگی', 0, '2025-07-14 09:25:10', '2025-07-14 09:25:10'),
(17, 'نگرانم که دیگران مرا ترک کنند یا به من صدمه بزنند.', 'اضطراب', 0, '2025-07-14 09:25:10', '2025-07-14 09:25:10'),
(18, 'احساس می‌کنم دیگران همیشه وقتی به آن‌ها نیاز دارم در کنارم هستند.', 'وابستگی', 1, '2025-07-14 09:25:10', '2025-07-14 09:25:10');
INSERT INTO `ras_questions` (`id`, `question_text`, `is_reverse`, `created_at`, `updated_at`) VALUES
(1, 'اکثر مردم از من جسورتر و قاطع‌تر هستند.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(2, 'به دلیل کمرویی، از بیرون رفتن با جنس مخالف خودداری می‌کنم.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(3, 'وقتی غذای رستوران به میل من نیست، خیلی راحت اعتراض می‌کنم.', 0, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(4, 'مواظبم که به دیگران آسیب نرسانم، حتی اگر خودم آسیب ببینم.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(5, 'اگر فروشنده‌ای بخواهد به زور جنسی را که دوست ندارم نشان دهد، به سختی می‌توانم «نه» بگویم.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(6, 'وقتی از من کاری بخواهند، می‌پرسم «چرا؟»', 0, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(7, 'مواقعی پیش می‌آید که نمی‌دانم چه بگویم.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(8, 'از درخواست پول از دوستان یا آشنایان اجتناب می‌کنم.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(9, 'از اینکه در جمع غریبه‌ها باشم، احساس ناراحتی می‌کنم.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(10, 'برای شروع مکالمه با افراد غریبه تردید دارم.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(11, 'وقتی فروشنده‌ای زحمت زیادی برای نشان دادن چیزی به من کشیده و من آن را نمی‌خواهم، به سختی می‌توانم بگویم «نمی‌خواهم».', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(12, 'وقتی کسی مرا اذیت می‌کند، نمی‌توانم چیزی بگویم و بعداً خودم را سرزنش می‌کنم.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(13, 'از رد کردن درخواست‌های غیرمنطقی دیگران احساس ناراحتی می‌کنم.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(14, 'اگر کسی در سینما جلوی من بلند صحبت کند، نمی‌توانم از او بخواهم آرام باشد.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(15, 'از اینکه بخواهم چیزی را که خریده‌ام پس بدهم، احساس ناراحتی می‌کنم.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(16, 'اگر یکی از نزدیکانم مرا ناراحت کند، نمی‌توانم به او بگویم.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(17, 'در موقعیت‌های اجتماعی، خودم را مضطرب و دستپاچه احساس می‌کنم.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(18, 'در بحث‌های گروهی، نمی‌توانم نظراتم را بیان کنم.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(19, 'از اینکه از رئیسم درخواست مرخصی کنم، احساس ناراحتی می‌کنم.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(20, 'وقتی کار خوبی انجام می‌دهم، دوست دارم دیگران از من تعریف کنند.', 0, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(21, 'نمی‌توانم به راحتی از دیگران تعریف کنم.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(22, 'وقتی دیگران از من تعریف می‌کنند، احساس خوبی دارم.', 0, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(23, 'خیلی راحت می‌توانم با دیگران شوخی کنم.', 0, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(24, 'از انتقاد کردن از دیگران، حتی اگر اشتباه کرده باشند، خودداری می‌کنم.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(25, 'وقتی احساس می‌کنم حق با من است، از بحث کردن با دیگران لذت می‌برم.', 0, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(26, 'وقتی کاری را خوب انجام می‌دهم، احساس رضایت می‌کنم.', 0, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(27, 'نمی‌توانم به راحتی احساساتم را با دیگران در میان بگذارم.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(28, 'از اینکه بخواهم با رئیسم درباره حقوقم صحبت کنم، احساس ناراحتی می‌کنم.', 1, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(29, 'وقتی از من تعریف می‌کنند، احساس می‌کنم لیاقتش را دارم.', 0, '2025-07-14 09:34:15', '2025-07-14 09:34:15'),
(30, 'وقتی کسی مرا فریب می‌دهد، خیلی راحت می‌توانم اعتراض کنم.', 0, '2025-07-14 09:34:15', '2025-07-14 09:34:15');
INSERT INTO `rotter_questions` (`id`, `question_number`, `option_a`, `option_b`) VALUES
(1, 1, 'وقتی در یک کار موفق می‌شوم، بیشتر به شانس نسبت می‌دهم.', 'وقتی در یک کار موفق می‌شوم، بیشتر به تلاش و کوشش خودم نسبت می‌دهم.'),
(2, 2, 'وقتی برنامه‌هایم خوب پیش می‌روند، این به شانس بستگی دارد.', 'وقتی برنامه‌هایم خوب پیش می‌روند، این به تصمیم‌ها و اعمال خودم بستگی دارد.'),
(3, 3, 'اگر در زندگی با مشکل مواجه شوم، بیشتر به شرایط بیرونی نسبت می‌دهم.', 'اگر در زندگی با مشکل مواجه شوم، بیشتر مسئولیت آن را به عهده خودم می‌دانم.'),
(4, 4, 'مقدار موفقیت من در زندگی بیشتر به اتفاقات بیرونی بستگی دارد.', 'مقدار موفقیت من در زندگی بیشتر به تلاش و انتخاب‌های خودم بستگی دارد.'),
(5, 5, 'وقتی دیگران به من کمک می‌کنند، بیشتر به شانس آن‌ها نسبت می‌دهم.', 'وقتی دیگران به من کمک می‌کنند، این نتیجه رابطه و تعامل خودم با آن‌هاست.'),
(6, 6, 'اگر کارهایم درست پیش نرود، دلیلش شرایط بیرونی است.', 'اگر کارهایم درست پیش نرود، به دنبال دلایل درونی و اشتباهات خودم می‌گردم.'),
(7, 7, 'وقتی یک هدف را می‌خواهم، بیشتر به کمک دیگران و شانس امید دارم.', 'وقتی یک هدف را می‌خواهم، بیشتر به توانایی‌ها و برنامه‌ریزی خودم امیدوارم.'),
(8, 8, 'مقدار موفقیت و شکست در زندگی بیشتر به شانس بستگی دارد.', 'مقدار موفقیت و شکست در زندگی بیشتر به رفتار و انتخاب‌های خودم بستگی دارد.'),
(9, 9, 'در مسائل مهم زندگی، کنترل چندانی ندارم و شرایط بیرونی تصمیم می‌گیرد.', 'در مسائل مهم زندگی، بیشتر کنترل امور را خودم به عهده دارم.'),
(10, 10, 'اگر اتفاقات خوبی در زندگی‌ام می‌افتد، دلیلش بیشتر شانس است.', 'اگر اتفاقات خوبی در زندگی‌ام می‌افتد، دلیلش تلاش و عملکرد خودم است.'),
(11, 11, 'اگر کسی به من لطمه بزند، آن را به شانس یا سرنوشت نسبت می‌دهم.', 'اگر کسی به من لطمه بزند، به رفتار و انتخاب‌های خودم فکر می‌کنم.'),
(12, 12, 'زندگی‌ام تحت کنترل عوامل بیرونی است که نمی‌توانم تغییر دهم.', 'زندگی‌ام تحت کنترل خودم است و می‌توانم آن را تغییر دهم.'),
(13, 13, 'نتایج کارهایم بیشتر از عوامل بیرونی نشأت می‌گیرد.', 'نتایج کارهایم بیشتر از تلاش و تصمیمات خودم ناشی می‌شود.'),
(14, 14, 'اگر در کاری شکست بخورم، آن را به شانس و شرایط بد نسبت می‌دهم.', 'اگر در کاری شکست بخورم، به ضعف‌ها و اشتباهات خودم توجه می‌کنم.'),
(15, 15, 'موفقیت‌هایم بیشتر به شانس و اتفاقات خوب بستگی دارد.', 'موفقیت‌هایم بیشتر به برنامه‌ریزی و کوشش خودم بستگی دارد.'),
(16, 16, 'احساس می‌کنم سرنوشت و دیگران کنترل زندگی‌ام را دارند.', 'احساس می‌کنم کنترل زندگی‌ام را خودم دارم.'),
(17, 17, 'اگر در مسائل مهم شکست بخورم، مقصر شرایط بیرونی است.', 'اگر در مسائل مهم شکست بخورم، مقصر خودم هستم.'),
(18, 18, 'موفقیت‌های بزرگ در زندگی بیشتر به شانس بستگی دارد.', 'موفقیت‌های بزرگ در زندگی بیشتر به تصمیمات و تلاش‌های من بستگی دارد.'),
(19, 19, 'اگر زندگی‌ام به خوبی پیش نمی‌رود، دلیلش عوامل بیرونی است.', 'اگر زندگی‌ام به خوبی پیش نمی‌رود، باید رفتار و تصمیمات خودم را تغییر دهم.'),
(20, 20, 'موفقیت‌های مهم به طور کلی تصادفی هستند.', 'موفقیت‌های مهم نتیجه برنامه‌ریزی و کار سخت هستند.'),
(21, 21, 'اگر مشکلاتی دارم، بیشتر به دلایل بیرونی فکر می‌کنم.', 'اگر مشکلاتی دارم، بیشتر به راه‌حل‌های درونی و شخصی فکر می‌کنم.'),
(22, 22, 'کنترل زندگی من بیشتر در دست عوامل بیرونی است.', 'کنترل زندگی من بیشتر در دست خودم است.'),
(23, 23, 'سرنوشت زندگی من بیشتر از خودم به دیگران بستگی دارد.', 'سرنوشت زندگی من بیشتر به تصمیمات و رفتارهای خودم بستگی دارد.');
