INSERT INTO `scs_lf_questions` (`id`, `question_text`, `subscale`, `created_at`, `updated_at`) VALUES
(1, 'وقتی جنبه‌هایی از خودم را که دوست ندارم می‌بینم، خودم را سرزنش می‌کنم.', 'خودانتقادی', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(2, 'وقتی در چیزی شکست می‌خورم، بیش از حد احساس ناکامی می‌کنم.', 'بیش‌تطبیقی', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(3, 'وقتی اوضاع بد پیش می‌رود، به یاد می‌آورم که همه انسان‌ها گاهی شکست می‌خورند.', 'انسانیت مشترک', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(4, 'وقتی شکست می‌خورم، احساس می‌کنم فقط من در جهان این‌طورم.', 'انزوا', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(5, 'سعی می‌کنم نسبت به جنبه‌هایی از شخصیتم که دوست ندارم، درک و صبور باشم.', 'مهربانی با خود', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(6, 'وقتی غمگینم، بیش از حد روی احساسات منفی‌ام تمرکز می‌کنم.', 'بیش‌تطبیقی', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(7, 'وقتی احساس ناکامی می‌کنم، به یاد می‌آورم که این بخشی از تجربه انسانی است.', 'انسانیت مشترک', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(8, 'وقتی اوضاع سخت می‌شود، با خودم سختگیرانه رفتار می‌کنم.', 'خودانتقادی', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(9, 'وقتی چیزی مرا ناراحت می‌کند، سعی می‌کنم احساساتم را متعادل نگه دارم.', 'ذهن‌آگاهی', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(10, 'وقتی احساس می‌کنم تنها هستم، به یاد می‌آورم که همه انسان‌ها گاهی این احساس را دارند.', 'انسانیت مشترک', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(11, 'وقتی رنج می‌کشم، با خودم سرد و بی‌رحم هستم.', 'خودانتقادی', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(12, 'وقتی رنج می‌کشم، با خودم مهربانم.', 'مهربانی با خود', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(13, 'وقتی غمگینم، فکر می‌کنم فقط من این احساسات را دارم.', 'انزوا', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(14, 'وقتی احساس درد می‌کنم، سعی می‌کنم با آرامش به آن نگاه کنم.', 'ذهن‌آگاهی', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(15, 'سعی می‌کنم ناکامی‌هایم را به‌عنوان بخشی از تجربه مشترک انسانی ببینم.', 'انسانیت مشترک', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(16, 'وقتی خودم را ارزیابی می‌کنم، بیش از حد از خودم انتقاد می‌کنم.', 'خودانتقادی', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(17, 'وقتی اتفاق بدی برایم می‌افتد، سعی می‌کنم آن را از منظر وسیع‌تری ببینم.', 'ذهن‌آگاهی', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(18, 'وقتی اوضاع خوب پیش نمی‌رود، احساس می‌کنم از دیگران جدا افتاده‌ام.', 'انزوا', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(19, 'وقتی دوران سختی را سپری می‌کنم، به خودم محبت و توجهی که نیاز دارم می‌دهم.', 'مهربانی با خود', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(20, 'وقتی ناراحتم، بیش از حد در احساساتم غرق می‌شوم.', 'بیش‌تطبیقی', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(21, 'به خاطر نقص‌هایم خودم را تحقیر می‌کنم.', 'خودانتقادی', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(22, 'وقتی چیزی دردناک است، سعی می‌کنم بدون قضاوت به آن نگاه کنم.', 'ذهن‌آگاهی', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(23, 'نسبت به نقص‌ها و ناکامی‌هایم شکیبا و بردبارم.', 'مهربانی با خود', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(24, 'وقتی چیزی مرا ناراحت می‌کند، بیش از حد در آن غرق می‌شوم.', 'بیش‌تطبیقی', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(25, 'وقتی در چیزی شکست می‌خورم، فکر می‌کنم دیگران موفق‌تر از من هستند.', 'انزوا', '2025-07-14 09:10:17', '2025-07-14 09:10:17'),
(26, 'وقتی احساس درد عاطفی می‌کنم، سعی می‌کنم با خودم با محبت رفتار کنم.', 'مهربانی با خود', '2025-07-14 09:10:17', '2025-07-14 09:10:17');
