INSERT INTO `shq_questions` (`id`, `question_number`, `text`, `dimension`) VALUES
(1, 1, 'من اغلب سعی می‌کنم مردم را بخندانم.', 'شوخ‌طبعی اجتماعی'),
(2, 2, 'من در شرایط سخت و استرس‌زا هم شوخی می‌کنم.', 'شوخ‌طبعی در بحران'),
(3, 3, 'دوست دارم دیگران را با شوخی‌های خودم سرگرم کنم.', 'شوخ‌طبعی اجتماعی'),
(4, 4, 'گاهی برای خنداندن دیگران، دیگران را مسخره می‌کنم.', 'شوخ‌طبعی منفی'),
(5, 5, 'حتی وقتی ناراحتم، باز هم شوخی می‌کنم.', 'شوخ‌طبعی در بحران'),
(6, 6, 'وقتی در جمع هستم، افراد را با شوخی جذب می‌کنم.', 'شوخ‌طبعی اجتماعی'),
(7, 7, 'با شوخی، تنش‌ها را در موقعیت‌های ناراحت‌کننده کاهش می‌دهم.', 'شوخ‌طبعی در بحران'),
(8, 8, 'شوخی کردن با دیگران به من احساس قدرت می‌دهد.', 'شوخ‌طبعی منفی'),
(9, 9, 'اغلب به خودم می‌خندم.', 'شوخ‌طبعی مثبت'),
(10, 10, 'شوخی باعث می‌شود آدم‌ها با هم صمیمی‌تر شوند.', 'شوخ‌طبعی مثبت'),
(11, 11, 'برای نشان دادن هوشم گاهی افراد را دست می‌اندازم.', 'شوخ‌طبعی منفی'),
(12, 12, 'در شرایط بحرانی، شوخ‌طبعی کمکم می‌کند آرام‌تر شوم.', 'شوخ‌طبعی در بحران'),
(13, 13, 'خنده باعث کاهش استرسم می‌شود.', 'شوخ‌طبعی در بحران'),
(14, 14, 'گاهی شوخی‌هایم دیگران را ناراحت می‌کند.', 'شوخ‌طبعی منفی'),
(15, 15, 'شوخی کردن راهی برای فرار از مشکلات است.', 'شوخ‌طبعی در بحران'),
(16, 16, 'دوست دارم با شوخی، حال دیگران را بهتر کنم.', 'شوخ‌طبعی اجتماعی'),
(17, 17, 'مردم من را آدم شوخ‌طبعی می‌دانند.', 'شوخ‌طبعی اجتماعی'),
(18, 18, 'شوخی کردن باعث می‌شود احساس شادابی کنم.', 'شوخ‌طبعی مثبت'),
(19, 19, 'شوخی با دیگران نشان‌دهنده قدرت من است.', 'شوخ‌طبعی منفی'),
(20, 20, 'در جمع‌ها معمولاً سعی می‌کنم دیگران را بخندانم.', 'شوخ‌طبعی اجتماعی'),
(21, 21, 'شوخ‌طبعی بخشی از شخصیت من است.', 'شوخ‌طبعی مثبت'),
(22, 22, 'من از شوخی به عنوان ابزار دفاعی استفاده می‌کنم.', 'شوخ‌طبعی در بحران'),
(23, 23, 'شوخی کردن با ضعف‌های دیگران کار بامزه‌ای است.', 'شوخ‌طبعی منفی'),
(24, 24, 'شوخی کردن باعث می‌شود بیشتر احساس ارتباط کنم.', 'شوخ‌طبعی مثبت'),
(25, 25, 'در جلسات رسمی هم گاهی شوخی می‌کنم.', 'شوخ‌طبعی اجتماعی'),
(26, 26, 'با شوخی‌های خودم دیگران را از خجالت درمی‌آورم.', 'شوخ‌طبعی اجتماعی'),
(27, 27, 'شوخی برای من راهی برای بروز خشم است.', 'شوخ‌طبعی منفی'),
(28, 28, 'با شوخی از موقعیت‌های سخت عبور می‌کنم.', 'شوخ‌طبعی در بحران'),
