INSERT INTO `spi_questions` (`id`, `question_number`, `text`) VALUES
(1, 1, 'آیا هنگام صحبت کردن در جمع احساس ترس می‌کنید؟'),
(2, 2, 'آیا هنگام ملاقات با افراد جدید احساس نگرانی و اضطراب دارید؟'),
(3, 3, 'آیا از حضور در مهمانی‌ها و اجتماعات دوری می‌کنید؟'),
(4, 4, 'آیا از صحبت کردن در جمع اجتناب می‌کنید؟'),
(5, 5, 'آیا در موقعیت‌های اجتماعی علائمی مانند تعریق یا تپش قلب دارید؟'),
(6, 6, 'آیا احساس می‌کنید در موقعیت‌های اجتماعی کنترلی روی خودتان ندارید؟'),
(7, 7, 'آیا از نگاه کردن به دیگران در جمع می‌ترسید؟'),
(8, 8, 'آیا از صحبت کردن تلفنی اجتناب می‌کنید؟'),
(9, 9, 'آیا هنگام حضور در جمع احساس خجالت می‌کنید؟'),
(10, 10, 'آیا از صحبت کردن با افراد غریبه ناراحت می‌شوید؟'),
(11, 11, 'آیا از شرکت در جلسات یا کلاس‌های بزرگ اجتناب می‌کنید؟'),
(12, 12, 'آیا هنگام صحبت کردن با دیگران دچار لرزش صدا می‌شوید؟'),
(13, 13, 'آیا از توجه و نگاه دیگران به خودتان احساس ناراحتی می‌کنید؟'),
(14, 14, 'آیا از حضور در مکان‌های شلوغ و پر جمعیت پرهیز می‌کنید؟'),
(15, 15, 'آیا هنگام حضور در جمع دچار خشکی دهان می‌شوید؟');
