INSERT INTO `stories` (`id`, `title`, `author`, `published_at`, `price`, `cover`, `created_at`, `updated_at`, `slug`, `des`, `genre_id`, `category_id`, `deleted_at`, `views_count`, `likes_count`, `avg_rating`, `ratings_count`) VALUES
(45, 'تست', 'سیریسر', '13280498', 1, 'Uploads/stories/6880ac9970e46.png', '2025-07-23 09:14:33', '2025-07-23 22:09:49', 'تست', '<p>لورم ایپسوم یا طرح‌نما (به انگلیسی: Lorem ipsum) به متنی آزمایشی و بی‌معنی در صنعت چاپ، صفحه‌آرایی و طراحی گرافیک گفته می‌شود. طراح گرافیک از این متن به عنوان عنصری از ترکیب بندی برای پر کردن صفحه و ارایه اولیه شکل ظاهری و کلی طرح سفارش گرفته شده استفاده می نماید، تا از نظر گرافیکی نشانگر چگونگی نوع و اندازه فونت و ظاهر متن باشد.معمولا طراحان گرافیک برای صفحه‌آرایی، نخست از متن‌های آزمایشی و بی‌معنی استفاده می‌کنند تا صرفا به مشتری یا صاحب کار خود نشان دهند که صفحه طراحی یا صفحه بندی شده بعد از اینکه متن در آن قرار گیرد چگونه به نظر می‌رسد و قلم‌ها و اندازه‌بندی‌ها چگونه در نظر گرفته شده‌است. از آنجایی که طراحان عموما نویسنده متن نیستند و وظیفه رعایت حق تکثیر متون را ندارند و در همان حال کار آنها به نوعی وابسته به متن می‌باشد آنها با استفاده از محتویات ساختگی، صفحه گرافیکی خود را صفحه‌آرایی می‌کنند تا مرحله طراحی و صفحه‌بندی را به پایان برند.<br></p>', NULL, NULL, '2025-07-23 22:09:49', 0, 0, 0.00, 0),
(46, 'kldsjfklsdjfkljsd', 'sdlkfjhskjdhfklsd', NULL, 0, 'Uploads/stories/68815509ccab1.png', '2025-07-23 21:32:59', '2025-07-23 21:33:10', 'kldsjfklsdjfkljsd', '<p>sdfknkjdshkfjhdsf</p><p>sdlkhfjhksdhkfjhsd</p><p>flsdkhfkjgsdkjgfkjsdjkfsdf</p>', NULL, NULL, '2025-07-23 21:33:10', 0, 0, 0.00, 0),
