INSERT INTO `trust_questions` (`id`, `subscale_id`, `question_text`, `is_reverse`, `created_at`, `updated_at`) VALUES
(1, 1, 'من می‌توانم رفتارهای شریکم را به‌خوبی پیش‌بینی کنم.', 0, '2025-07-09 22:27:00', '2025-07-09 22:27:00'),
(2, 1, 'شریکم به‌طور مداوم رفتارهای قابل انتظاری دارد.', 0, '2025-07-09 22:27:00', '2025-07-09 22:27:00'),
(3, 1, 'من می‌دانم شریکم در موقعیت‌های مختلف چگونه واکنش نشان می‌دهد.', 0, '2025-07-09 22:27:00', '2025-07-09 22:27:00'),
(4, 1, 'رفتار شریکم اغلب غیرقابل پیش‌بینی است.', 1, '2025-07-09 22:27:00', '2025-07-09 22:27:00'),
(5, 1, 'من معمولاً می‌توانم حدس بزنم شریکم چه تصمیمی می‌گیرد.', 0, '2025-07-09 22:27:00', '2025-07-09 22:27:00'),
(6, 2, 'من می‌توانم روی پایبندی شریکم به قول‌هایی که می‌دهد حساب کنم.', 0, '2025-07-09 22:27:00', '2025-07-09 22:27:00'),
(7, 2, 'شریکم همیشه صادقانه با من رفتار می‌کند.', 0, '2025-07-09 22:27:00', '2025-07-09 22:27:00'),
(8, 2, 'من به شریکم اعتماد کامل دارم.', 0, '2025-07-09 22:27:00', '2025-07-09 22:27:00'),
(9, 2, 'شریکم گاهی در مورد احساساتش به من دروغ می‌گوید.', 1, '2025-07-09 22:27:00', '2025-07-09 22:27:00'),
(10, 2, 'من مطمئنم که شریکم در مواقع نیاز از من حمایت می‌کند.', 0, '2025-07-09 22:27:00', '2025-07-09 22:27:00'),
(11, 3, 'من باور دارم که شریکم حتی در شرایط سخت به من وفادار می‌ماند.', 0, '2025-07-09 22:27:00', '2025-07-09 22:27:00'),
(12, 3, 'شریکم به رابطه ما متعهد است.', 0, '2025-07-09 22:27:00', '2025-07-09 22:27:00'),
