INSERT INTO `tyl_questions` (`id`, `schema_key`, `schema_title`, `question_text`, `question_number`) VALUES
(228, 'PUNITIVENESS', 'تنبیه‌گری', 'فکر می‌کنم عدالت یعنی اینکه هر کس به‌خاطر اشتباهاتش تنبیه شود.', 228),
