(39, 'EMOTIONAL_DEPRIVATION', 'محرومیت عاطفی', 'اغلب حسرت یک رابطه عاطفی گرم و صمیمی را می‌خورم.', 39),
(37, 'EMOTIONAL_DEPRIVATION', 'محرومیت عاطفی', 'احساس می‌کنم که هیچ‌کس واقعاً نمی‌خواهد با من ارتباط عمیق داشته باشد.', 37),
(36, 'EMOTIONAL_DEPRIVATION', 'محرومیت عاطفی', 'فکر می‌کنم نیازهای عاطفی‌ام هرگز به‌طور کامل برآورده نمی‌شوند.', 36),
(35, 'EMOTIONAL_DEPRIVATION', 'محرومیت عاطفی', 'اغلب احساس می‌کنم که از نظر عاطفی تنها و منزوی هستم.', 35),
(34, 'EMOTIONAL_DEPRIVATION', 'محرومیت عاطفی', 'می‌ترسم که هرگز کسی مرا به‌طور کامل دوست نداشته باشد.', 34),
(32, 'EMOTIONAL_DEPRIVATION', 'محرومیت عاطفی', 'فکر می‌کنم دیگران نمی‌توانند به من عشق و محبت واقعی بدهند.', 32),
(33, 'EMOTIONAL_DEPRIVATION', 'محرومیت عاطفی', 'احساس می‌کنم که در زندگی‌ام حمایت عاطفی کافی ندارم.', 33),
(31, 'EMOTIONAL_DEPRIVATION', 'محرومیت عاطفی', 'به ندرت پیش می‌آید که احساس کنم کسی واقعاً به من نزدیک است.', 31),
(29, 'EMOTIONAL_DEPRIVATION', 'محرومیت عاطفی', 'به نظرم دیگران نمی‌توانند نیازهای عاطفی‌ام را برآورده کنند.', 29),
(30, 'EMOTIONAL_DEPRIVATION', 'محرومیت عاطفی', 'احساس می‌کنم که همیشه از نظر عاطفی چیزی کم دارم.', 30),
(28, 'EMOTIONAL_DEPRIVATION', 'محرومیت عاطفی', 'اغلب احساس تنهایی می‌کنم، حتی وقتی با دیگران هستم.', 28),
(27, 'EMOTIONAL_DEPRIVATION', 'محرومیت عاطفی', 'احساس می‌کنم که هیچ‌کس واقعاً مرا درک نمی‌کند یا به من اهمیت نمی‌دهد.', 27),
(26, 'MISTRUST', 'بی‌اعتمادی/بدرفتاری', 'فکر می‌کنم دنیا پر از افرادی است که نمی‌توان به آن‌ها اعتماد کرد.', 26),
(25, 'MISTRUST', 'بی‌اعتمادی/بدرفتاری', 'می‌ترسم که اگر خودم را نشان دهم، دیگران از من سوءاستفاده کنند.', 25),
(24, 'MISTRUST', 'بی‌اعتمادی/بدرفتاری', 'احساس می‌کنم که دیگران به من دروغ می‌گویند یا مرا گول می‌زنند.', 24),
(23, 'MISTRUST', 'بی‌اعتمادی/بدرفتاری', 'به ندرت پیش می‌آید که احساس کنم می‌توانم به کسی کاملاً اعتماد کنم.', 23),
(21, 'MISTRUST', 'بی‌اعتمادی/بدرفتاری', 'فکر می‌کنم دیگران فقط به فکر منافع خودشان هستند.', 21),
(22, 'MISTRUST', 'بی‌اعتمادی/بدرفتاری', 'اغلب احساس می‌کنم که دیگران قصد فریب دادن من را دارند.', 22),
(20, 'MISTRUST', 'بی‌اعتمادی/بدرفتاری', 'می‌ترسم که دیگران از اعتماد من سوءاستفاده کنند.', 20),
(19, 'MISTRUST', 'بی‌اعتمادی/بدرفتاری', 'احساس می‌کنم که دیگران به من خیانت خواهند کرد.', 19),
(18, 'MISTRUST', 'بی‌اعتمادی/بدرفتاری', 'به سختی می‌توانم به دیگران اعتماد کنم.', 18),
(17, 'MISTRUST', 'بی‌اعتمادی/بدرفتاری', 'من معمولاً به نیت‌های خوب دیگران شک دارم.', 17),
(16, 'MISTRUST', 'بی‌اعتمادی/بدرفتاری', 'مردم معمولاً اهداف پنهانی دارند که به ضرر من است.', 16),
(15, 'MISTRUST', 'بی‌اعتمادی/بدرفتاری', 'اگر به کسی نزدیک شوم، دیر یا زود مرا خواهد رنجاند.', 15),
(14, 'MISTRUST', 'بی‌اعتمادی/بدرفتاری', 'من اغلب انتظار دارم که دیگران به من آسیب بزنند یا از من سوءاستفاده کنند.', 14),
(12, 'ABANDONMENT', 'رهاشدگی/بی‌ثباتی', 'احساس می‌کنم که نمی‌توانم بدون افراد مهم زندگی‌ام زندگی کنم.', 12),
(13, 'ABANDONMENT', 'رهاشدگی/بی‌ثباتی', 'فکر می‌کنم هر لحظه ممکن است کسی که دوستش دارم از من دور شود.', 13),
(11, 'ABANDONMENT', 'رهاشدگی/بی‌ثباتی', 'اغلب نگرانم که دیگران مرا به خاطر شخص دیگری ترک کنند.', 11),
(10, 'ABANDONMENT', 'رهاشدگی/بی‌ثباتی', 'می‌ترسم که افراد نزدیکم به من خیانت کنند یا مرا رها کنند.', 10),
(9, 'ABANDONMENT', 'رهاشدگی/بی‌ثباتی', 'احساس می‌کنم که نمی‌توانم به حضور دائمی دیگران در زندگی‌ام اعتماد کنم.', 9),
(8, 'ABANDONMENT', 'رهاشدگی/بی‌ثباتی', 'فکر می‌کنم روابطم با دیگران پایدار نیستند.', 8),
(7, 'ABANDONMENT', 'رهاشدگی/بی‌ثباتی', 'اغلب احساس ناامنی می‌کنم وقتی با افراد مهم زندگی‌ام هستم.', 7),
(6, 'ABANDONMENT', 'رهاشدگی/بی‌ثباتی', 'می‌ترسم که اگر به کسی نزدیک شوم، او مرا ترک کند.', 6),
(5, 'ABANDONMENT', 'رهاشدگی/بی‌ثباتی', 'احساس می‌کنم که همیشه باید مراقب باشم که دیگران را از خود نرنجانم تا ترکم نکنند.', 5),
(4, 'ABANDONMENT', 'رهاشدگی/بی‌ثباتی', 'می‌ترسم که کسانی که به آن‌ها تکیه دارم، دیگر به من توجه نکنند.', 4),
(3, 'ABANDONMENT', 'رهاشدگی/بی‌ثباتی', 'احساس می‌کنم که دیر یا زود رابطه‌های مهم زندگی‌ام به پایان می‌رسند.', 3),
(2, 'ABANDONMENT', 'رهاشدگی/بی‌ثباتی', 'همیشه نگرانم که افرادی که به آن‌ها وابسته‌ام من را ترک کنند یا بمیرند.', 2),
(1, 'ABANDONMENT', 'رهاشدگی/بی‌ثباتی', 'من نگرانم که افراد مهم زندگی‌ام ناگهان من را ترک کنند.', 1),
(229, 'PUNITIVENESS', 'تنبیه‌گری', 'اغلب خودم را به خاطر نقص‌هایم سرزنش می‌کنم.', 229),
(230, 'PUNITIVENESS', 'تنبیه‌گری', 'احساس می‌کنم که اشتباهات باید با عواقب سختی همراه باشند.', 230),
(231, 'PUNITIVENESS', 'تنبیه‌گری', 'فکر می‌کنم باید برای هر اشتباه بهایی پرداخت.', 231),
(232, 'PUNITIVENESS', 'تنبیه‌گری', 'احساس می‌کنم که نمی‌توانم به‌راحتی از خطاهای دیگران بگذرم.', 232);
